// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":105,"question":"تشهد المدن في الآونة الأخيرة ازدحامًا في عُمرانها وسُكَّانها، شملت في ذلك مقابر المسلمين، وقد لوحظ أنَّ القبر يُفتح بعد ثمانية أشهر من دفن الميت به، ويُجمع رفات الميت، ثم يُوضع ميتٌ آخر، فما رأي سماحتكم في ذلك، خصوصًا إذا اختلفت أعمالُ مَن يُدفنون في القبر: فمنهم الصَّالح، ومنهم غير ذلك، والله أعلم بأعمالهم؟","title":"ما الحكم عند ازدحام القبور بالموتى؟","answer":"الجواب: درس مجلسُ هيئة كبار العلماء هذه المسألة مرات، وقرر أنَّ الواجب أن تُخصص مقابر تسع الناس، خصوصًا في الجزيرة والبلاد التي توجد في هذه الجزيرة؛ لأن فيها أراضٍ كثيرة والحمد لله، والسيارات موجودة، فلا بدّ أن تُخصص أراضٍ تسع الناس، ويكون كل قبرٍ على حدةٍ، كما فعل النبيُّ ﷺ والصحابةُ في المدينة وفي مكة وفي غيرهما، فكلُّ إنسانٍ يُقْبَر وحده، إلا إذا وقعت كارثةٌ أو وقعت مصيبةٌ وكثر الموتى؛ فلا مانع أن يُجمع اثنان وثلاثة في قبرٍ واحدٍ عند الضَّرورة وعند الحاجة، كما جرى يوم أُحُدٍ لما كثر القتلى، والمسلمون فيهم جراحات، ويخافون من شرِّ العدو؛ فلذلك دفنوا الاثنين والثلاثة في قبرٍ واحدٍ، وكان النبيُّ ﷺ يُقدِّم أفضلَهم إلى القبلة.\nأما إذا كان الناسُ في أمنٍ وعافيةٍ فالواجب أن يُجعل كلُّ واحدٍ في قبرٍ، ولا يُجعل معه غيره، والأراضي موجودة.\nوإذا ضاقت الأمور، وكانوا في بلدٍ ضيقٍ، ولا توجد فيه أرضٍ؛ جاز لهم أن يدفنوا الجماعة، لكن الغالب على البلاد أنه توجد فيها أراضٍ، فإذا ابتعدوا عن المدينة وجدوا أراضٍ يستطيعون أن يدفنوا فيها الواحدَ وحده، وينقلوه بالسيارات والقطارات والعربات وغير ذلك.","link":"https://binbaz.org.sa/fatwas/3222/ما-الحكم-عند-ازدحام-القبور-بالموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0086.mp3","categories":["حمل الميت ودفنه"]},{"id":145,"question":"يُلاحظ أن الجنازة بعدما تخرج من الحرم المكي وهي في طريقها إلى المقبرة عدَّة أمور:الأمر الأول: يقوم بعضُ الأشخاص بالصياح قائلًا: \"وحِّدوه\".ثانيًا: يقف حامل الجنازة عند منطقة تُسمَّى \"مقراة الفاتحة\" ويقرأ فيها بسورة الفاتحة.ثالثًا: تتابع الجنازة سيرها نحو المقبرة وأيضًا يصيح بعضُ الأشخاص: \"وحِّدوه\".ورابعًا: عندما تصل الجنازة إلى باب المقبرة يُوقفها الحاملون لها ويُنزلونها على الأرض، ويصيح أحدُهم: \"ماذا تشهدون عليه؟\" ثم يحملونها مرةً أخرى إلى المقبرة.وخامسًا: وفي المقبرة عندما ينزل الميت وينزل معه بعضُ الأشخاص لتسوية القبر، وبعد أن يُسوَّى القبر يقوم أحدُهم بالأذان في القبر ويُقيم الصلاة.فهل هذا من الشرع في شيءٍ؟","title":"حكم عبارات \"وحِّدوه\" في الجنائز ونحوها","answer":"الجواب: كل هذه بدع: رفع الصوت بـ\"وحِّدوه\" لا أصل له، بل السنة مع الجنازة خفض الصوت، والإنسان يُحاسب نفسه، ويتذكر حال الميت، وماذا يُقال له؟ وماذا يُجيب؟ ولا يقول: \"وحِّدوه\" أو \"اذكروا الله\"، فكل هذا ما له أصل.\nفعلى الإنسان أن يُحاسب نفسه فيما بينه وبين الله وهو ماشٍ مع الجنازة، فيتذكر الموت، ويتذكر عاقبة الموتى، وما يُقال للميت، ويكون عنده خوفٌ وخشوعٌ، ولا يقف عند أي مكانٍ ويقول: \"اقرؤوا الفاتحة\"، لا في مكة، ولا في غير مكة، فهذا بدعة.\nكذلك كونه يضعه ويقول: \"ماذا تشهدون عليه؟\" هذا لا أصل له، يُريدون أن يفضحوه، يقولون: هو فاسق، وإلا هذا غلطٌ، إذا شهد عليه الناسُ من دون طلبٍ لا بأس، إذا قالوا: نعم، جزاه الله خيرًا، وعمل معروفًا، فجزاهم الله خيرًا، والحمد لله أنتم شهداء الله في أرضه، أمَّا أنه يضعها أو يقول: ما تشهدون عليه؟ كل الناس، فلا، هذا بدعة، ما له أصلٌ، وهذا من أسباب الفضيحة أيضًا، أن يفضحه الناسُ إذا كان فاسقًا.\nكذلك الأذان والإقامة في القبر، أو عند قبر؛ لا أصل لها، بل بدعة -نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/3682/حكم-عبارات-وحدوه-في-الجناىز-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0138.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":247,"question":"هل يجوز إزالة غطاء الوجه عن الميت إذا وُضع في قبره، سواء كان رجلًا أم امرأةً؟","title":"حكم كشف وجه الميت عند وضعه في القبر","answer":"الجواب: لا، الميت لا يُزال عن وجهه شيءٌ، لا المرأة، ولا الرجل، إذا وُضع في اللَّحد يُترك على حاله بكفنه، لا يُزال عن وجهه شيءٌ، بل يُغطَّى الوجه، سواء كان رجلًا أو امرأةً، ولا أصل لما يقوله بعضُ العامَّة من كشف الوجه، ولكن تحلّ العُقد وهي في محلِّها، تُحل وتُترك في محلِّها، ولكن لا يكشف الوجهَ ولا غيره.","link":"https://binbaz.org.sa/fatwas/4136/حكم-كشف-وجه-الميت-عند-وضعه-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0289.mp3","categories":["حمل الميت ودفنه"]},{"id":256,"question":"ما حكم قراءة الفاتحة بعد دفن الميت؟","title":"ما حكم قراءة الفاتحة بعد دفن الميت؟","answer":"الجواب: لا أصل لهذا، لا قبل دفنه، ولا بعد دفنه، ولا عند دفنه، الدفن فيه مسائل منكرة، منها: قراءة القرآن في الدفن قبله أو بعده أو حينه.\nومنها: إقامة الأذان في القبر، والإقامة في القبر، فهذا لا أصلَ له.\nومنها: قراءة القرآن في القبر، كل هذا شيء لا أصل له.\nومنها: ما يُسمونه بالتلقين، وقد ورد في أحاديث غير صحيحةٍ موضوعة؛ كونه يقف عند رأسه ويقول: \"ثم خرجت من الدنيا وشهدت: أن لا إله إلا الله، وأنَّ محمدًا رسول الله، ورضيتَ بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ رسولًا، وبالقرآن إمامًا\"، هذا شيءٌ لا أصلَ له، الأحاديث الواردة فيه غير صحيحةٍ، وإنما هو معروفٌ من بعض أهل الشام، وليسوا بقدوةٍ.\nالحاصل أنَّ التلقين لا أصلَ له، ولا ينتفع به الميت، الميت على ما مات عليه، ما هو على التلقين الجديد، بل هو على ما مات عليه.\nوالذي شرعه الرسولُ ﷺ أنه كان يقف بعد الموت بعد الدفن ويقول لأصحابه  وأرضاهم: استغفروا لأخيكم، واسألوا له التَّثبيت، فإنه الآن يُسأل، هذا الذي ينفع: الاستغفار له والدعاء، فكان إذا فرغ من دفن الميت وقف عليه عليه الصلاة والسلام وقال: استغفروا لأخيكم، واسألوا له التَّثبيت، فإنه الآن يُسأل، فهذا هو المشروع بعد الدفن: يُوقَف عليه ويُقال: \"اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم ثبته على الحقِّ\"، كلمات بهذا المعنى، كما أمر النبيُّ ﷺ، أما التَّلقين الذي يفعله بعضُ الناس الآن: يا فلان ابن فلانة، يُناديه باسم أمه كما جاء في الأحاديث الموضوعة، ثم يقول....... إلى آخره، هذا لا أصل له.","link":"https://binbaz.org.sa/fatwas/4248/ما-حكم-قراءة-الفاتحة-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0299.mp3","categories":["حمل الميت ودفنه"]},{"id":690,"question":"يقول: يا سماحة الشيخ: رأيت البعض من الناس عندما يضعون الميت في اللحد يقومون بالأذان والإقامة فوقه، هل هذا صحيح؟","title":"حكم الأذان والإقامة عند دفن الميت","answer":"الجواب: هذا بدعة، الأذان في القبر والإقامة في القبر بدعة لا تجوز، كل هذا لا يجوز، لا بعد الدفن ولا قبل الدفن، كله لا يجوز.","link":"https://binbaz.org.sa/fatwas/15849/حكم-الاذان-والاقامة-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/58804.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":721,"question":"هل يجوز أن تُدفن المرأةُ مع زوجها أو العكس في قبرٍ واحدٍ؟","title":"ما حكم دفن المرأة مع زوجها والعكس؟","answer":"الجواب: السُّنة عدم ذلك، السنة أن يكون كل واحدٍ وحده، الرجل وحده، والمرأة وحدها، وهكذا بقية الناس، وهكذا كان النبيُّ يفعل في البقيع والصحابة، يدفنون كل واحدٍ وحده. لكن لو دعت الضَّرورة والحاجة الشَّديدة إلى مثل ذلك -مثل: لو نزل وباء ومات الناسُ كثيرًا، أو قتال وصارت ملحمة، وصار فيها أموات كثيرون يشقّ إفراد كل واحدٍ- جاز الجمع بين الرجال والنساء، وجاز الجمع بين الرجلين والثلاثة، كما فعله النبيُّ يوم أُحُدٍ عليه الصلاة والسلام، يوم أُحُدٍ دفن الرجلين والثلاثة في قبرٍ واحدٍ للضَّرورة، للحاجة الشَّديدة؛ لأن القتلى كثيرون، والمسلمون فيهم جراحات، فاحتاجوا إلى هذا، ولا بأس أن تُدفن المرأةُ مع زوجها، لا بأس عند الحاجة، لكن عند عدم الحاجة وكون الموتى قليل..... لا يجوز الجمعُ بين الاثنين والثلاثة إلا للضَّرورة والحاجة.","link":"https://binbaz.org.sa/fatwas/20560/ما-حكم-دفن-المراة-مع-زوجها-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0518فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["حمل الميت ودفنه"]},{"id":783,"question":"مثل مَن يقول عند المقبرة أو عند تشييع الجنازة: \"وَحِّدُوه\" وما أشبه ذلك؟","title":"حكم قول \"وَحِّدُوه\" عند تشييع الجنازة ونحوها","answer":"الجواب: هذا ما له أصل، لا، السنة السكوت عند تشييع الجنازة، الإنسان يُنصت ويُفكِّر في مصيره، وأنه سوف يأتي عليه ما أتى على مَن قبله، ومَن هو معه يُفكِّر في مصيره، يُفكِّر في القبر وما يتعلق بالآخرة، أما أن يصيح: وحِّدوه، وحِّدوه، قولوا \"لا إله إلا الله\"، هذا ما له أصلٌ.","link":"https://binbaz.org.sa/fatwas/20718/حكم-قول-وحدوه-عند-تشييع-الجنازة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0604حكم من يقول عند تشيع الجنازة وحدوه وما أشبه ذلك؟ ابن باز فتاوى المحاضرات.mp3","categories":["حمل الميت ودفنه"]},{"id":841,"question":"يقوم بعضُ الناس بعد دفن الميت بالدعاء، ويقوم مَن معه بالتأمين على دعائه؟","title":"حكم الدعاء والتأمين عليه بعد دفن الميت","answer":"الجواب: يُستحب بعد الدفن الدعاء للميت بالثبات والمغفرة، كان النبيُّ ﷺ إذا فرغ  من دفن الميت وقف عليه وقال: استغفروا لأخيكم، وسَلُوا له التَّثبيت، فإنه الآن يُسأل، كل واحدٍ يُستحب له أن يدعو لأخيه، فيستغفر له، ويسأل له الثبات، فإذا دعا واحدٌ وأمَّنوا فلا أعلم فيه شيئًا، المسلمون شيءٌ واحدٌ، إذا دعا واحدٌ منهم وقالوا: آمين، حصل المقصود إن شاء الله.","link":"https://binbaz.org.sa/fatwas/20870/حكم-الدعاء-والتامين-عليه-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0665حكم الدعاء بعد دفن الميت والتأمين على هذا الدعاء ؟ ابن باز فتاوى المحاضرات.mp3","categories":["حمل الميت ودفنه"]},{"id":890,"question":"إذا شُيِّعت جنازة يتبعها عددٌ كثيرٌ من الرجال من أهل بلده، مضمون سؤاله: أنَّهم يتكلَّمون في أمور الدنيا، يمشون خلف الجنازة ويتكلَّمون ويتحدَّثون في أمور الدُّنيا؟","title":"حكم التكلم بأمور الدنيا أثناء تشييع الجنازة","answer":"الجواب: السُّنة لمن شيَّع الجنازة أن يتدبَّر مصيرها ومصيره، وما يُقال له، وما تُسأل عنه، وأنه سوف يكون وسوف يصير إلى ما صارت إليه، فلا يشتغل بالدنيا، ولا الحديث بها، بل يُفكر في مصيره، ويحرص على أن يستحضر أنه صائرٌ إلى ما صار إليه، ويتذكر هذا الموكب، وهذا المصير، حتى يعدَّ له عدَّته اللازمة، هذا هو المشروع للمؤمن مع الجنائز، وليس محلّ ضحكٍ.","link":"https://binbaz.org.sa/fatwas/20926/حكم-التكلم-بامور-الدنيا-اثناء-تشييع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0721ما حكم التكلم بأمور الدنيا عند تشيع الجنازة؟ابن باز فتاوى المحاضرات.mp3","categories":["حمل الميت ودفنه"]},{"id":1011,"question":"ورد إلينا عددٌ من الأسئلة، يسأل أصحابُها عن حكم القراءة على الميت في حال الدفن في المقبرة، أو بعد الدفن، كنحو قراءة الفاتحة على وجه الخصوص، وعن حكم الأذان والإقامة في أُذن الميت قبل الدفن؟","title":"حكم القراءة على الميت حال الدفن والأذان في أُذُنه","answer":"الجواب: هذا من البدع: القراءة على الميت بعد الدفن، أو عند القبر، أو الأذان في القبر، أو الإقامة في القبر، أو القراءة في القبر، كلها بدع لا تجوز، ليس لها أصلٌ، ولم يفعلها المصطفى ﷺ ولا أصحابه، فلا يجوز للمؤمن أن يقرأ على الميت عند القبور، ولا يقرأ عليه في القبر، ولا وهو موضوعٌ في بيته، أو في القبر، أو عند القبر، ولا يُقيم أو يُؤذن في القبر، كل هذا لا أصلَ له. إنما يُقرأ عند الإنسان المُحْتَضر قبل أن يموت؛ لعله يستفيد وينتفع، وأما بعد الموت فقد انقطع عملُه إلا مما قدَّم، كما في الحديث الصَّحيح: يقول النبيُّ ﷺ: إذا مات ابنُ آدم انقطع عملُه إلا من ثلاثٍ: صدقة جارية –يعني: وقفًا أجراه- أو علم يُنتفع به، أو ولد صالح يدعو له.","link":"https://binbaz.org.sa/fatwas/21065/حكم-القراءة-على-الميت-حال-الدفن-والاذان-في-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0861حكم القراءة على الميت في حال الدفن في المقبرة أوبعد الدفن؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","حمل الميت ودفنه"]},{"id":1707,"question":"ما الضَّابط في تأخير دفن الميت؟","title":"ما الضَّابط في تأخير دفن الميت؟","answer":"الجواب:\nليس له ضابط، إلا تحري الشيء الذي ينفع، إمَّا لكي يحضر أناسٌ من أقاربه الجنازةَ، أو لأجل تأخّر الغاسل، أو بسبب الكفن، والسنة الإسراع به؛ فالنبي عليه الصلاة والسلام قال: أسرعوا بالجنازة، فإن تكن صالحةً فخيرٌ تُقدِّمونها إليه، فالسنة الإسراع بها إلا من علَّةٍ.\nس: قد يُؤخِّرها بعضُهم يومين أو ثلاثة أيام إلى أن يَقْدُم ابنُه من الخارج أو ما أشبه؟\nج: لا، ليس هذا عدلًا، السنة الإسراعُ بها.","link":"https://binbaz.org.sa/fatwas/21813/ما-الضابط-في-تاخير-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضَّابط في تأخير دفن الميت.mp3","categories":["حمل الميت ودفنه"]},{"id":1906,"question":"الساحر لما يُقام عليه الحدّ يُدفَن مع المسلمين؟","title":"أين يُدفن الساحر إذا أقيم عليه الحد؟","answer":"لا، الساحر يُدفن مع الكفار، ما هو من المسلمين، السحرة كفرة.","link":"https://binbaz.org.sa/fatwas/22018/اين-يدفن-الساحر-اذا-اقيم-عليه-الحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين يدفن الساحر إذا أقيم عليه الحد.mp3","categories":["حمل الميت ودفنه"]},{"id":2074,"question":"هل يجوز للإنسان أن يشترط إذا مات أن يُدْفَن في بيته؟","title":"هل يجوز دَفْنُ ميت في بيته بناء على طلبه؟","answer":"الجواب:\nلا، لو شرط ذلك فهو شرطٌ باطلٌ، ويُدْفَن في مقابر المسلمين، ولا يُدْفَن في بيته.\nس: قالوا: لماذا دُفِنَ أبو بكر وعمر في بيت رسول الله ﷺ؟\nج: لأنَّهم أصحابه الخواص، فدُفِنَا معه عليه الصلاة والسلام، فصارت حجرتُه مقبرةً للجميع –للثلاثة- مقبرة خاصَّة.\nس: لعلَّةٍ لهما؟\nج: لأنَّهما صاحباه الخاصَّان رضي الله عنهما.\nس: فيكون خاصًّا بهما؟\nج: اجتهادًا من الصَّحابة.","link":"https://binbaz.org.sa/fatwas/22192/هل-يجوز-دفن-ميت-في-بيته-بناء-على-طلبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز أن يشترط إذا مات أن يدفن في بيته.mp3","categories":["حمل الميت ودفنه"]},{"id":2189,"question":"هل مِن السُّنة أن يُقال بعد دفن كل ميتٍ: اسألوا لأخيكم التثبيت؟","title":"حكم قول \"اسألوا لأخيكم التثبييت\" بعد الدفن","answer":"الجواب:\nنعم، مثلما كان النبي ﷺ يفعل: استغفروا لأخيكم، وسلوا له التَّثبييت.\nس: تارةً وتارةً أم دائمًا؟\nج: المعروف أنه كان إذا فرغ من الدفن قال هذا.","link":"https://binbaz.org.sa/fatwas/22312/حكم-قول-اسالوا-لاخيكم-التثبييت-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول اسألوا لأخيكم التثبييت بعد الدفن.mp3","categories":["حمل الميت ودفنه"]},{"id":2508,"question":"يجوز الجمع بين الرجل والمرأة في قبر واحد؟","title":"حكم الجمع بين الرجل والمرأة في قبر واحد","answer":"الجواب:\nإذا دعت الضرورة، وإلا السُّنة كل واحد في قبر، لكن إذا كثر الموتى واشتد على الناس، يجعل بينهم تراب حاجز أفضل.\nس: ولو كانوا غير مَحْرَم؟\nالشيخ: ولو غير مَحْرَمها.","link":"https://binbaz.org.sa/fatwas/22638/حكم-الجمع-بين-الرجل-والمراة-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الرجل والمرأة في قبر واحد.mp3","categories":["حمل الميت ودفنه"]},{"id":3021,"question":"نقل الجنازة مِن بلد إلى بلد؟","title":"حكم نقل الجنازة مِن بلد إلى بلد","answer":"الجواب: الأفضل عدم النقل؛ لأن الصحابة ما كانوا ينقلون من مات، يُدفن في محله، إذا كان في مقبرة مسلمة الحمد لله.\nس: حتى لو كان وَصّى؟\nالشيخ: ولَو وصّى، لا يتكلّفون، كان الصحابة: الذي مات في مكة، والذي مات في المدينة، والذي مات في خيبر، والذي مات في الشام، والذي مات في اليمن، ما أحد يُنقل، ما كانوا ينقلونهم.","link":"https://binbaz.org.sa/fatwas/23180/حكم-نقل-الجنازة-من-بلد-الى-بلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقل الجنازة من بلد إلى بلد.mp3","categories":["حمل الميت ودفنه"]},{"id":3092,"question":"حكم وضع الميت في التابوت قبل الدفن؟","title":"حكم وضع الميت في التابوت","answer":"الجواب: ما هو بمشروع، المشروع وضعه في الأرض، النبي ﷺ وضعوه في الأرض، الصحابة وضعوه في الأرض.\nس: يَحْرُم؟\nالشيخ: لا، أقل أحواله يعني تَرْكُه أوْلى، ينبغي أن يوضع في الأرض كما فعل الصحابة بالنبي ﷺ، وكما كان الصحابة يفعلون .","link":"https://binbaz.org.sa/fatwas/23252/حكم-وضع-الميت-في-التابوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع الميت في التابوت.mp3","categories":["حمل الميت ودفنه"]},{"id":3334,"question":"الأجر المترتب على دفن الميت؟","title":"ما الأجر المترتب على دفن الميت؟","answer":"الجواب: إن حضر الصلاة له أجران، قيراطان، وإن حضر أحدهما له أجر واحد، وهو أجر عظيم أعظم من الجبل.","link":"https://binbaz.org.sa/fatwas/23500/ما-الاجر-المترتب-على-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأجر المترتب على دفن الميت.mp3","categories":["حمل الميت ودفنه"]},{"id":5150,"question":"يقول هذا السائل يا سماحة الشيخ: تشهد المدن في الآونة الأخيرة ازدحامًا في عُمرانها وسُكَّانها، شملت في ذلك مقابر المسلمين، وقد لوحظ أنَّ القبر يُفتح بعد ثمانية أشهر من دفن الميت به، ويُجمع رفات الميت، ثم يُوضع ميتٌ آخر، فما رأي سماحتكم في ذلك، خصوصًا إذا اختلفت أعمالُ مَن يُدفنون في القبر: فمنهم الصَّالح، ومنهم غير ذلك، والله أعلم بأعمالهم؟","title":"ما حكم فتح القبر لوضع ميت آخر فيه؟","answer":"الجواب: درس مجلسُ هيئة كبار العلماء هذه المسألة مرات، وقرر أنَّ الواجب أن تُخصص مقابر تسع الناس، خصوصًا في الجزيرة والبلاد التي ..... الجزيرة؛ لأن فيها أراضي كثيرة والحمد لله، والسيارات موجودة، فلا بدّ أن تُخصص أراضٍ تسع الناس، ويكون كل قبرٍ على حدةٍ، كما فعل النبيُّ ﷺ والصحابةُ في المدينة وفي مكة وفي غيرهما، فكلُّ إنسانٍ يُقْبَر وحده، إلا إذا وقعت كارثةٌ أو وقعت مصيبةٌ وكثر الموتى؛ فلا مانع أن يُجمع اثنان وثلاثة في قبرٍ واحدٍ عند الضَّرورة وعند الحاجة، كما جرى يوم أحدٍ لما كثر القتلى، والمسلمون فيهم جراحات، ويخافون من شرِّ العدو؛ فلذلك دفنوا الاثنين والثلاثة في قبرٍ واحدٍ، وكان النبيُّ ﷺ يُقدِّم أفضلَهم إلى القبلة - عليه الصلاة والسلام-. أما إذا كان الناسُ في أمنٍ وعافيةٍ فالواجب أن يُجعل كلُّ واحدٍ في قبرٍ، ولا يُجعل معه غيره، والأراضي موجودة. وإذا ضاقت الأمور، وكانوا في بلدٍ ضيقٍ، ولا توجد فيه أرضٍ؛ جاز لهم أن يدفنوا الجماعة، لكن الغالب على البلاد أنه توجد فيها أراضٍ، فإذا ابتعدوا عن المدينة وجدوا أراضٍ يستطيعون أن يدفنوا فيها الواحدَ وحده، وينقلوه بالسيارات والقطارات والعربات وغير ذلك.","link":"https://binbaz.org.sa/fatwas/30065/ما-حكم-فتح-القبر-لوضع-ميت-اخر-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 86.mp3","categories":["حمل الميت ودفنه"]},{"id":5383,"question":"ما يُفعل في بعض البلدان: إذا مرَّ على القبر فترةً وصار رميمًا أخذوه على جنبٍ ودفنوا ثانيًا؟","title":"ما حكم نبش القبر ليُدفن فيه آخر؟","answer":"الجواب: لا، ما ينبغي هذا، ينبغي أن تكون مقابر متعددة بقدر حاجة الناس، ولا تُنبش، الميت محترم. أما إذا كان للضَّرورة فالضَّرورات لها أحكامها، كما دفن النبي يوم أُحُد الاثنين والثلاثة جميعًا، وإذا كان البلاد ضيقة والمكان ضيق ودفنوا هذا مع هذا، إذا دعت الحاجةُ؛ لا بأس. س: ولو لم يبقَ من عظامه شيء؟ ج: إذا دعت الحاجةُ لا بأس.[1]","link":"https://binbaz.org.sa/fatwas/31121/ما-حكم-نبش-القبر-ليدفن-فيه-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/mnbr_006.mp3","categories":["حمل الميت ودفنه"]},{"id":5657,"question":"هل تتفضل حفظكم الله ببيان صفة دفن الميت، وهل يجوز دفنه في جميع الأوقات، أثابكم الله؟","title":"ما صفة الدفن الشرعي للميت؟","answer":"الجواب: السُّنة في دفن الميت أن يُلْحَد له في الجهة الغربية من قبره، وأن يُوضع فيه مُكفَّنًا مستورًا، حتى الوجه لا يُكشَف، يكون مستورًا كله في اللَّحْدِ، ثم تُنْصَب عليه اللّبن، وتُحفظ اللّبن باللّبنات التي تسدّ المنافذ، ثم يُهال عليه التراب، ثم يُرفع عن الأرض قدر شبرٍ؛ حتى يعلم أنه قبر، هذا هو السُّنة في الدَّفن.[1]","link":"https://binbaz.org.sa/fatwas/31694/ما-صفة-الدفن-الشرعي-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 003.mp3","categories":["حمل الميت ودفنه"]},{"id":5715,"question":"هل الأفضل حل العقد من عند رأس الميت، وترك العقد التي عند رجليه، ووسطه، أم تحل كلها؟","title":"حكم حل عقد الكفن عند وضع الميت في قبره","answer":"الجواب: العقد التي يربط بها الكفن تحل كلها هذا الأفضل، السنة تحل كلها في القبر، إن وضع في قبره حلت العقد كلها، أولها وآخرها هذا السنة، محلها تبقى في محلها.","link":"https://binbaz.org.sa/fatwas/1021/حكم-حل-عقد-الكفن-عند-وضع-الميت-في-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_43.mp3","categories":["حمل الميت ودفنه","الأدعية والأذكار"]},{"id":5730,"question":"هل هناك ذكر معين للذين يحملون الجنازة؟","title":"ما يقال عند اتباع الجنازة؟","answer":"الجواب: السنة الصمت عند حمل الجنازة، السنة الصمت إلا في نفسك، أما هذا يقول: اذكروا الله، وحدوا الله ، هذه بدعة، ما لها أصل، فإذا جاءت الجنازة يسيرون متفكرين في مصير الجنازة، وماذا يقال لها؟ وماذا تجيب؟ الأمر عظيم، فالجنائز واتباعها للموعظة. فالسنة لمن حضرها، أو تبعها أن يفكر، وينظر، فسوف يجري عليه ما جرى عليها، سوف يموت كما ماتت فكر في المصير، وماذا يقال لهذه الجنازة؟ وماذا تقول؟ فالهول عظيم! أما كونه يقول: اذكروا الله، اشهدوا لها بكذا وكذا، فهذا ما له أصل.","link":"https://binbaz.org.sa/fatwas/1031/ما-يقال-عند-اتباع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_53.mp3","categories":["الأدعية والأذكار","حمل الميت ودفنه"]},{"id":5806,"question":"الميت في التابوت أحيانًا للضرورة كأن كان غريقًا، أو كان تنتن جسمه؟","title":"حكم وضع الميت في تابوت داخل القبر","answer":"الجواب: إذا غرق ينقل من بلاد إلى بلاد، فيوضع في قبر لا بأس. السؤال: لكن يدفن في القبر مع التابوت؟ الشيخ: إذا كان يخشى منه لا يخرج إذا كان يضرهم، لو أخرجوه لا يخرج.  وأما إذا كان لا ، لا يضر يخرج، ويوضع في اللحد، أما إذا كان ... لآذى الناس، وشق عليهم ريحه يدفن بالتابوت، ويكفي هذا، نسأل الله للجميع التوفيق، وصلاح النية، والعمل.","link":"https://binbaz.org.sa/fatwas/1154/حكم-وضع-الميت-في-تابوت-داخل-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_156.mp3","categories":["حمل الميت ودفنه"]},{"id":5809,"question":"بالنسبة لمن يبني مسجدًا، ويأمر بدفنه فيه؛ قياسًا على فعل الرسول؟","title":"بنى مسجدًا وأوصى أن يدفن فيه","answer":"الجواب: لا، لا يدفن؛ لأن الرسول ما دفن في المسجد، الرسول دفن في الحجرة في بيته، لكن لما وسع الوليد أدخل الحجرة، وضمها إلى المسجد. فالنبي ما دفن في المسجد ﷺ دفن في بيته، بيت عائشة، ولكن بعض أمراء القرن الأول أدخله في المسجد للتوسعة، أدخل الحجرة برمتها، وقد غلط في ذلك، ولكن وقع ما وقع.","link":"https://binbaz.org.sa/fatwas/1133/بنى-مسجدا-واوصى-ان-يدفن-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_139.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":5821,"question":"الميت في التابوت أحيانًا للضرورة كأن كان غريقًا، أو كان تنتن جسمه؟","title":"حكم وضع الميت في تابوت داخل القبر","answer":"الجواب: إذا غرق ينقل من بلاد إلى بلاد، فيوضع في قبر لا بأس. السؤال: لكن يدفن في القبر مع التابوت؟ الشيخ: إذا كان يخشى منه لا يخرج إذا كان يضرهم، لو أخرجوه لا يخرج.  وأما إذا كان لا ، لا يضر يخرج، ويوضع في اللحد، أما إذا كان ... لآذى الناس، وشق عليهم ريحه يدفن بالتابوت، ويكفي هذا، نسأل الله للجميع التوفيق، وصلاح النية، والعمل.","link":"https://binbaz.org.sa/fatwas/1154/حكم-وضع-الميت-في-تابوت-داخل-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_156.mp3","categories":["حمل الميت ودفنه"]},{"id":5827,"question":"عندما يدفن الميت، ويحثى عليه التراب، ضروري أن يوطؤوا عليه الأرجل، أم لا؟","title":"حكم وطء القبر بالأقدام أثناء الدفن","answer":"الجواب: إذا دفن الميت لا يوطأ، ولكن يوارى التراب بالأيدي، ويرش بالماء، وتوضع عليه الحصباء، ثم يدعى له بالمغفرة، والثبات، هذا المشروع، ولا يوطأ، لا يوطأ بالرجل، ولا يداس عليه النبي -عليه الصلاة والسلام- قال: لا تصلوا في القبور، ولا تجلسوا عليها رواه مسلم في الصحيح. وقال -عليه الصلاة والسلام-: لأن يجلس أحدكم على جمرة، فتصل إلى جلده، فتحرقه خير له من أن يجلس على قبر.","link":"https://binbaz.org.sa/fatwas/1169/حكم-وطء-القبر-بالاقدام-اثناء-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_168.mp3","categories":["حمل الميت ودفنه"]},{"id":5831,"question":"إذا مات الميت بالليل فهل الأفضل دفنه في الليل، أم يؤجل حتى يصبح؟","title":"هل يجوز دفن الميت ليلاً؟","answer":"الجواب: إذا مات في أول الليل فيصلى عليه بعد صلاة المغرب، أو العشاء فهذا أفضل. أما إذا مات في أثناء الليل، فالأفضل أن يؤخر حتى يصلى عليه صلاة الفجر، ويكثر عليه الجمع، ويشيع، هذا أفضل له، وأفضل لأهله، يدعون له، ويستغفرون له.","link":"https://binbaz.org.sa/fatwas/1170/هل-يجوز-دفن-الميت-ليلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_169.mp3","categories":["حمل الميت ودفنه"]},{"id":5832,"question":"ما حكم من يوصي بدفنه في محل قد دفن فيه أهله، وأولاده، هل ننفذ وصيته، أم لا؟","title":"حكم من أوصى بأن يدفن في مقبرة دفن فيها أقاربه","answer":"الجواب: إذا أوصى بأن يدفن في المقبرة التي دفن فيها أقاربه؛ فلا بأس، إذا كان ما في كلفة، أما إذا كان فيه كلفة مثل نقله من بلاد إلى بلاد، ما في حاجة، يدفن مع المسلمين في أي مكان، لكن إذا كان في البلاد، ولا فيه كلفة؛ فهذا حسن، حتى تسهل زيارتهم، حتى الذي يزورهم يزورهم جميعً في مقبرة واحدة فيه مصلحة. لكن إذا كان فيه كلفة، وخسائر، ونفقة فلا حاجة إلى هذا الشيء، ولا تنفذ هذه الوصية، فالذي ينقل من بلاد إلى بلاد، وفيه موجب، وفيه كلفة على أهل الميت، وقد يكون ثقيل، وقد يكون أهله فقراء. فالحاصل: أنه لا أصل للنقل، ولم يكن الصحابة ينقلون من بلد إلى بلد، رضي الله عنهم وأرضاهم. فالأفضل عدم النقل إلا من حاجة إلا من مصلحة، كالذي يموت بين الكفار، ينقل، يدفن بين المسلمين، لا بأس، وإن نقل ليدفن بين أهله بدون مشقة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1165/حكم-من-اوصى-بان-يدفن-في-مقبرة-دفن-فيها-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_164.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":5836,"question":"إذا توفى في الرياض، وقال: ادفنوني في المدينة؟","title":"حكم من أوصى أن يدفن في بلد غير بلده","answer":"الجواب: لا، ما هو بمشروع هذا، إذا مات في الرياض لا ينقل إلى المدينة، ولا لغير المدينة، وإذا مات في الخرج ما ينقل للرياض، وإذا مات في الخرج لا ينقل إلى الحوطة، وهكذا ما له حاجة، تكلف بلا حاجة، الأولى عدم تنفيذ هذه الوصية.","link":"https://binbaz.org.sa/fatwas/1166/حكم-من-اوصى-ان-يدفن-في-بلد-غير-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_165.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":5837,"question":"الدعاء للميت بعد الدفن؟","title":"صفة الدعاء بعد الدفن","answer":"الجواب: استغفروا لأخيكم، واسألوا له التثبيت فإنه الآن يسأل يقول: اللهم اغفر لفلان، اللهم ثبته بالقول الثابت. السؤال: جماعة، ولا فرادى؟ الجواب: كل واحد يدعو بنفسه.","link":"https://binbaz.org.sa/fatwas/1161/صفة-الدعاء-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_160.mp3","categories":["الأدعية والأذكار","حمل الميت ودفنه"]},{"id":5839,"question":"ما حكم جعل أكثر من ميت في قبر واحد، ويفتح إذا وجد ميت من نفس العائلة، كما هو موجود في بعض الأمصار؟","title":"ما حكم وضع أكثر من ميت في القبر؟","answer":"الجواب: السنة أن يدفن كل واحد في قبر على حدة، هذا السنة؛ هكذا كان يفعل في عهد النبي ﷺ في البقيع، كل واحد على حدة، لا يدفن اثنين ثلاثة جميعًا. لكن إذا دعت الحاجة مثل: أموات كثيرون بسبب وباء، أو حرب، فمات أموات كثيرون، لا بأس أن يوضع اثنان، وثلاثة في قبر واحد، كما فعله النبي ﷺ يوم أحد حينما دفنوا اثنين وثلاثة جميعًا في قبر واحد يوم أحد؛ فإذا وقعت المصيبة، يعني أموات كثيرون، أو وباء مات فيه ناس كثيرون، فلا بأس أن يوضع اثنان وثلاثة في قبر واحد.","link":"https://binbaz.org.sa/fatwas/1167/ما-حكم-وضع-اكثر-من-ميت-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_166.mp3","categories":["حمل الميت ودفنه"]},{"id":6238,"question":"نبدأ بخبر عاجل على حسب ما قال صاحبه: توفي اليوم الشيخ حسن بن سعيد بن معيلي، أظن اليوم بالمستشفى التخصصي، فهل يجوز نقله إلى اليمن، أو إلى مكة، أو يدفن في مدينة الرياض، أفتونا -أثابكم الله- والتوقيع أولاده، وجماعته؟","title":"حكم نقل الميت من مكان وفاته إلى بلد ولادته وإقامته","answer":"الجواب: غفر الله له، غفر الله لحسن بن سعيد، هذا من إخواننا من الرؤساء في سبأ مأرب، غفر الله له، وأدخله الجنة.  فالذي نرى عدم نقله، يصلى عليه هنا، ويدفن في المقابر هنا؛ لأن النقل يترتب عليه مشاكل: أولاً: قد يقطعون منه الأمعاء وهذا تمثيل به لا يجوز، لئلا تخيس.  والأمر الثاني: ما هناك حاجة إلى نقله إلى اليمن، ولا إلى مكة، الإنسان يدفن في محله الذي مات فيه، ما دام فيه مقبرة للمسلمين يدفن مع المسلمين.  فالذي نرى أن لا ينقل، ولكن يدفن في مقابر المسلمين هنا، والحمد لله؛ سلامة من التكلف، وسلامة أيضًا من العدوان عليه، والتمثيل به من أجل نقله.","link":"https://binbaz.org.sa/fatwas/1753/حكم-نقل-الميت-من-مكان-وفاته-الى-بلد-ولادته-واقامته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_592.mp3","categories":["حمل الميت ودفنه"]},{"id":6280,"question":".جاء في المحاضرة أن المتوفي المحرم يدفن في إحراميه، فإذا توفى بحادث بدم .. ما الطريق؟","title":"مشروعية دفن المحرم في ثوبي الإحرام","answer":"الجواب: المتوفى في جهاد في المعركة، شهيد المعركة هذا يدفن بثيابه، ولو فيها دماء، لا يصلي عليه، ويدفن في ثيابه، شهيد المعركة في الجهاد الشرعي، إذا مات في المعركة؛ دفن في ثيابه، وينزع منه السلاح، والجلود، ويدفن في ثيابه بدمائه، ولا يغسل، ولا يصلى عليه، وهي شاهدة له يوم القيامة. وأما الذي في حادث لا، الذي في حادث يغسل، وينظف، ويحط عليه أكفان، وليس مثل شهيد المعركة، هذا يغسل، ويكفن، ويصلى عليه، ليس من جنس شهداء المعركة. وكذلك المحرم يغسل، ويصلى عليه، ويكفن في ثوبيه، النبي -عليه الصلاة والسلام- أمر الذي مات في الإحرام أن يغسل بماء، وسدر، وأن يكفن في ثوبيه إزاره، ورداءه، وألا يغطى رأسه، ولا وجهه، ولا يطيب، إذا مات محرمًا لا يطيب، ولا يغطى رأسه، ولا وجهه، ويدفن في ثوبيه إزراه، ورداءه، هكذا أمر النبي -عليه الصلاة والسلام-.  السؤال: لكن الثوبين توسخت من الحادث؟  الجواب: ولو توسخت، يدفن في ثوبيه، المحرم ما في حادث، المحرم ما طاح وهو محرم يدفن في ثوبيه...","link":"https://binbaz.org.sa/fatwas/1803/مشروعية-دفن-المحرم-في-ثوبي-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_644.mp3","categories":["حمل الميت ودفنه"]},{"id":6681,"question":"توفي جدي وله أربعة من العيال، ولدين وبنتين، فأوصى بقسم من بيته لبنات ولده، علمًا أن له عيال، فهل يجوز لنا تنفيذ ما أوصى به لبنات ولده، وما حكم الإسلام في ذلك؟","title":"حكم الوصية لبنات الولد","answer":"الجواب: الوصية لغير الوارث لا بأس بها، الوصية للوارث ممنوعة، أما الوصية لغير الوارث من أولاد أولاده من غير الوارثين لا بأس بها .. فله أن يوصي لغير الورثة بالثلث، فأقل، أما الورثة فليس يوصي لهم لا بقليل، ولا بكثير، أما غير الورثة كجد أم أبي أمه، وكأولاد بناته، وكأولاد إخوته، وكذا إخوته غير الوارثين؛ لأن له أولادًا، له أن يوصي بما يشاء بالثلث، فأقل، لكن إذا كان له أولاد، فالواجب العدل بينهم، إذا كان له أولاد  فلا يوصي لبعضهم دون بعض اتقوا الله واعدلوا بين أولادكم فيوصي للجميع، أو يدع الجميع. السؤال: ولو أوصى لأحد الورثة بإجازة الباقين؟ الجواب: إذا أجاز الباقون؛ فلا بأس للحديث، إلا أن يشاء الورثة، الحق لهم إذا أجازوه هم، إذا أجازوا وهم مرشدون، لا صغارًا، إذا أجازوه وهم مرشدون فلا بأس.","link":"https://binbaz.org.sa/fatwas/2550/حكم-الوصية-لبنات-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1045.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":6688,"question":"لي والدة توفيت في أمريكا، وقد دفنت في مقابر النصارى هناك؛ لأنه لا يوجد مقبرة للمسلمين في ذلك الوقت، والآن قد اشتريت مقبرة للمسلمين، فهل تنقل من مقبرة النصارى، وتوضع في مقبرة المسلمين؟","title":"حكم نبش قبر المسلم الذي دفن في مقابر الكفار لنقله","answer":"الجواب: نعم نعم، تنبش وينقل ما يوجد من عظامها، وآثارها إلى مقبرة المسلمين، وإذا كان ما في مقبرة تنبش، وتوضع في محل بعيد عن الكفار، وتدفن، و.. الأرض بها حتى لا يعتدى عليها حتى لا تكون بين النصارى، والكفار، لا يجوز الدفن مع الكفار أبدًا، ولكن إذا كان في مقبرة للمسلمين تدفن مع المسلمين، وتنبش من قبرها، وتنقل.  وإذا كان ما هناك مقبرة للمسلمين ينظر في محل بعيد عن الطرقات، فتدفن فيه، ويواسى محله، حتى لا يهتدى إليها، أو تنبش، أو يفعل بها شيء.","link":"https://binbaz.org.sa/fatwas/2535/حكم-نبش-قبر-المسلم-الذي-دفن-في-مقابر-الكفار-لنقله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1030.mp3","categories":["حمل الميت ودفنه"]},{"id":7059,"question":"والدي توفي منذ سنتين، وقد أوصاني -رحمه الله- بأن أكون في الوصية على ثلثه، وقد أخذت المال، وكان المبلغ لا بأس به، واشتريت به بضائع، وربح، والحمد لله، وأنا إن بعت، وزاد هذا المبلغ، وبدأت أعطي منه صدقات، وأعطي للمحتاج، وكذلك إذا أراد أحد دينًا؛ فإني أعطيه من ذلك المال، أما بالنسبة لي فإني آخذ منه دينًا إذا احتجت لذلك، وأقوم بإرجاعه، هل في هذا الأخذ شيء؟ أرجو أن تخبرني جزاك الله خيرًا، هل هو حلال أو حرام؟","title":"حكم الاقتراض من الثلث الموصى به في مجالات الخير","answer":"الجواب:\n\nهذا فيه خير كثير، ومصلحة، هذا على كل حال عمل طيب، وسعيها في تنميته، وكل ما ينفع الميت هذا كله طيب، وإن جعل في عقار يكون أثبت، في بيت، أو دكان، أو نخل .. يمكن شراء العقار، يكون أسلم وأثبت، وإلا فهذا عمل طيب، كونها تشتري به سلعًا، وينمو، وتعتني بأسباب الربح، وتتصدق بذلك. \n\nأما كونها تقترض فلا تقترض، وينبغي ألا تقترض من ذلك، بل تحفظه، وتعمل فيه ما ينميه، ويكثر ريعه، وهي لا تقترض.\n\nأما إن أرادت شيئًا من الربح؛ تراجع ولي الأمر، تراجع المحكمة، والمحكمة تفرض لها شيئًا، نصف الربح، أو ثلث الربح، أو ربع الربح، أو ما أشبه ذلك مما تراه المحكمة.","link":"https://binbaz.org.sa/fatwas/3048/حكم-الاقتراض-من-الثلث-الموصى-به-في-مجالات-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1441.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":7082,"question":"أفيد فضيلتكم أن والدي توفي، وقد أوصى بثلث ماله، يجعل في عقار يريع، يخرج من ريعه أضحية، وباقي ريعه يصرف في أعمال البر والخير، أفيد فضيلتكم بأن ثلث ماله لا يكفي في شراء عقار، فأرجو من فضيلتكم أن يبين لنا في أي شيء يوضع هذا المال؟","title":"حكم من أوصى بالاستثمار في شيء ولم يبلغ ثمنه","answer":"الجواب:\n\nإذا تيسر بعقار، ولو مشاعًا مثل سهم في بيت في عمارة، في أرض تغل في نخل اشتروا به، يعني ربع نخل، ثلث نخل، نصف نخل، نخلات معلومة في محل مرغوب حتى تضحوا منها كل سنة، والباقي في أعمال البر، يصرف في الفقراء، والمساكين، وعمارة المساجد، وحاجات المساجد، ونحو ذلك.\n\nأما إذا كان قليلًا، ما في حيلة، هذا يصرفه في جهة نافعة، مثل عمارة المساجد، وأشباهها، وإن ضحيتم منه حتى ينتهي، أو جعلتموه عند إنسان يتجر فيه، ويضحى من غلته، ويتصدق من غلته إذا تيسر من يقوم بذلك من الناس الطيبين الأمناء، يتجرون فيه، ثم يتصدق من غلته، ويضحى من غلته؛ لا بأس، أما إذا ما تيسر أن يقوم بذلك، ولا حصل من يتجر فيه؛ فإنه يجعل في مثل المسجد؛ حتى ينتفع بصلاة المسلمين فيه، وإقامة الحلقات العلمية فيه، ونحو ذلك، إذا كان قليلًا، ما فيه حيلة.","link":"https://binbaz.org.sa/fatwas/3078/حكم-من-اوصى-بالاستثمار-في-شيء-ولم-يبلغ-ثمنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1462.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":7211,"question":"عندما نقوم بدفن الميت، ما هي العبارة الصحيحة التي نقولها امتثالًا لقول الرسول ﷺ: استغفروا لأخيكم، واسألوا له الثبات؛ فإنه الآن يسأل؟","title":"الذكر الوارد عند دفن الميت وبعد الفراغ من دفنه","answer":"الجواب:\n\nعند الدفن يقال: بسم الله وعلى ملة رسول الله، وبعد الفراغ يستحب لهم أن يقفوا عليه، ويقولوا: اللهم اغفر لفلان، اللهم اغفر له، اللهم ثبته بالقول الثابت، لأن الرسول -عليه الصلاة والسلام- كان إذا فرغ من الدفن؛ وقف على الميت، وقال: اللهم اغفر له وثبته بالقول الثابت وقال: استغفروا لأخيكم، واسألوا له التثبيت؛ فإنه الآن يسأل يسأل له المغفرة والرحمة، والثبات على الحق، يقف بعض الوقت ثم ينصرف.\n\nالسؤال: يستقبل القبلة؟\n\nالجواب: ما هو بلازم، لا، ما هو بلازم على أي حال كان.","link":"https://binbaz.org.sa/fatwas/3250/الذكر-الوارد-عند-دفن-الميت-وبعد-الفراغ-من-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1583.mp3","categories":["الأدعية والأذكار","حمل الميت ودفنه"]},{"id":7298,"question":"رجل له أرض زراعية، توفي أحد أبنائه، وقام بدفنه في هذه الأرض، ثم توفي له ابن آخر بعد فترة من الزمن، فقام بإدخاله مع أخيه في هذا القبر، ثم بعد فترة قام بنقل عظام امرأته وإدخاله في نفس هذا القبر حيث إن قبرها تقرر أن يمضي عليه شارع عام، فأصبح هذا القبر يضم ثلاثة أشخاص، وبعد أن توفي هذا الرجل وكبر أبناؤه؛ أرادوا أن يقوموا بالبناء في هذه الأرض، ولكن أصبح هذا القبر بوسط هذه الأرض، ويشكل حرجًا لهم، والسؤال هل من الممكن نقل ما بقي من العظام من هذا القبر إلى مقابر المسلمين، حيث يتسنى لهم أن يستفيدوا من هذه الأرض؟","title":"حكم نبش رفات موتى دفنوا في قبر واحد","answer":"الجواب: هذا غلط دفنهم جميعًا في هذه الأرض، هذا من الغلط، بل الواجب أن يدفن كل واحد في قبر على حدة مع القدرة، وأن يكونوا في مقابر المسلمين، لا في أرضهم، ولا في بيتهم، ولا في حوشهم، الواجب أن يكونوا مع المسلمين في مقابر المسلمين.  فعلى الأولاد الموجودين أن ينقلوا العظام إلى المقبرة العامة، كل عظام في قبر تكون وحدها في حفرة وحدها، يسوى ظاهرها كالقبر؛ حتى تكون محترمة كبقية القبور، لا توطأ، ولا تمتهن، فيجتهدوا في عظام الأول وحدها، وعظام الثاني وحدها، وعظام الثالث وحدها، كل واحد في حفرة وحده، ثم يسوى ظاهرها كظاهر القبور في مقابر المسلمين، المقبرة التي حولهم، ولا بأس أن يستعملوا الأرض.","link":"https://binbaz.org.sa/fatwas/3373/حكم-نبش-رفات-موتى-دفنوا-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1691.mp3","categories":["حمل الميت ودفنه"]},{"id":7348,"question":"حكم دفن الميت في المسجد، واتخاذه مزارًا، ويستثمروا منه فلوس؟","title":"حكم دفن الموتى في المساجد واتخاذها قبورًا","answer":"الجواب:  هذا منكر، لا يجوز الدفن في المساجد، المساجد ما هي مقبرة، الموتى تدفن خارج المساجد،  في محلات في الصحراء، أما المسجد ما يجوز الدفن فيه، ولا يجوز أن يقام مسجد على القبور، لا يقبر فيه، ولا يقام على القبور الاثنين، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ينصحون ويعلمون، وإذا دفن في المسجد؛ ينبش وينقل إلى المقبرة، ولا يجوز بقاؤه في المسجد -نسأل الله الهداية-.","link":"https://binbaz.org.sa/fatwas/3416/حكم-دفن-الموتى-في-المساجد-واتخاذها-قبورا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1728.mp3","categories":["المساجد ومواضع السجود","حمل الميت ودفنه"]},{"id":7359,"question":"حكم دفن الميت في المسجد، واتخاذه مزارًا، ويستثمروا منه فلوس؟","title":"حكم دفن الموتى في المساجد واتخاذها قبورًا","answer":"الجواب:  هذا منكر، لا يجوز الدفن في المساجد، المساجد ما هي مقبرة، الموتى تدفن خارج المساجد،  في محلات في الصحراء، أما المسجد ما يجوز الدفن فيه، ولا يجوز أن يقام مسجد على القبور، لا يقبر فيه، ولا يقام على القبور الاثنين، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ينصحون ويعلمون، وإذا دفن في المسجد؛ ينبش وينقل إلى المقبرة، ولا يجوز بقاؤه في المسجد -نسأل الله الهداية-.","link":"https://binbaz.org.sa/fatwas/3416/حكم-دفن-الموتى-في-المساجد-واتخاذها-قبورا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1728.mp3","categories":["المساجد ومواضع السجود","حمل الميت ودفنه"]},{"id":7650,"question":"يقول سعد محمد السعيد المالكي من متوسطة العمشان ببلاد بني مالك في رسالته: من بلاد بني مالك إلى من يهمه الأمر، السلام عليكم ورحمة الله وبركاته.. وبعد:نفيدكم أنه يوجد لدينا بمسجدنا نعش لحمل الأموات ودكة غسل مصنوعة من الحديد ومغطاة بألواح بيلوت، ونحن لا نعلم هل هو جائز حمل الميت على هذا النوع من الحديد، أفيدونا جزاكم الله خيراً، والله يحفظكم ويرعاكم؟","title":"حكم حمل الميت على نعش من حديد","answer":"الجواب: لا نعلم في هذا شيئاً، حمله على خشب أو على ألواح من غير الخشب أو على حديد لا نعلم في هذا شيئاً، لكن الأولى أن يتخذ شيء خفيف حتى لا يشق على الحاملين؛ لأن الناس إذا حملوه على الأكتاف قد يشق عليهم ذلك، أما إذا حمل في السيارة فالأمر في هذا واسع، لكن الشيء الخفيف أولى بكل حال، الألواح الخفيفة يوضع عليها الميت ويحمل عليها إلى المقبرة هذا أولى من الشيء الثقيل، أما الحرج فلا حرج إن شاء الله في كونه من حديد أو من خشب، لكن إذا كان حديداً خفيفاً لا يشق على الناس فلا حرج، وإن كان ثقيلاً فينبغي تركه حتى لا يشق على الحاملين. نعم.","link":"https://binbaz.org.sa/fatwas/4788/حكم-حمل-الميت-على-نعش-من-حديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03602.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7712,"question":"المرسل عبد الكريم من الخفجي يسأل عن تلقين المقبور، يقول: السلام عليكم ورحمة الله وبركاته وبعد: أرجو عرض سؤالي هذا على فضيلة الشيخ المجيب، أود لو تعطوني فكرة عن التلقينة، هل هي صحيحة أم بدعة، تلقينة الميت عند نزوله في القبر، أفيدونا جزاكم الله خيراً؟","title":"حكم تلقين الميت بعد الدفن","answer":"الجواب: التلقين اختلف فيه العلماء، وهو أن يقال له: يا فلان! اذكر ما خرجت عليه من الدنيا: شهادة أن لا إله إلا الله وأن محمداً رسول الله.. إلى آخره، وقد جاء فيه بعض الأحاديث لكنها غير صحيحة، جاء في بعض الآثار عن بعض أهل الشام، والصواب أنه بدعة.. التلقين، لا يقال له: يا فلان! اذكر ما خرجت عليه من هذه الدنيا: شهادة أن لا إله إلا الله، وأن محمداً رسول الله، وأنك رضيت بالله رباً وبالإسلام ديناً وبمحمد رسولاً، والقرآن إماماً.. إلى آخره، هذا ليس له أصل يعتمد عليه، فالذي ينبغي تركه، هذا هو المعتمد لعدم الدليل، ولكن يستحب إذا فرغ الناس من دفن الميت يستحب الوقوف عليه، والدعاء له بالمغفرة والثبات، هذا المشروع، إذا فرغ الناس من دفن الميت يوقف عليه ويدعى له بالمغفرة والثبات، هكذا جاءت السنة كان النبي ﷺ إذا فرغ من الدفن وقف عليه وقال: استغفروا لأخيكم، وسلوا له التثبيت فإنه الآن يسأل هذه السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4911/حكم-تلقين-الميت-بعد-الدفن ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7878,"question":"من العراق وردتنا هذه الرسالة من مريم المرسلة مريم تقول فيها: هل أن الصندوق لوضع الموتى حرام على النساء أو الرجال هذا، ولفضيلتكم جزيل الشكر؟","title":"حكم استخدام الصناديق في دفن الموتى","answer":"الجواب: المشروع للموتى أن يدفنوا في التراب ولا يجعلوا في الصناديق، الصندوق ما فعله النبي ﷺ ولا فعله أصحابه رضي الله عنهم وأرضاهم، هذا خلاف السنة فلا ينبغي فعله؛ لأنه خلاف سنة نبينا ﷺ وخلاف ما فعله أصحابه وأهل العلم بعدهم.\nفالسنة أنه يكفن في ثلاثة أثواب بيض للرجل هذا هو الأفضل، وإن كفن في غيرها في سوداء أو خضراء أو زرقاء جاز، وإن كفن في ثوب واحد حتى ستره جميعه فلا بأس، لكن لا يوضع في صندوق بل يوضع على التراب، يوضع في اللحد على التراب ويوضع عليه اللبن الذي يسد اللحد، ثم يهال عليه التراب كما فعله نبينا ﷺ وفعله المسلمون، أما وضع الموتى في التوابيت والصناديق هذا لا أصل له، ولا ينبغي فعله. نعم.","link":"https://binbaz.org.sa/fatwas/5343/حكم-استخدام-الصناديق-في-دفن-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_057/05702.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7894,"question":"أيضاً يقول: إذا توفي إنسان يوم الخميس، بقي عند قبره أصدقاء أقاربه بحجة تسليمه لليلة الجمعة، فما هو الحكم؛ لأنه يقول: إنه إذا توفي عندنا الإنسان قبل الجمعة فإنه لا يترك إلا أن يسلم ليوم الجمعة، نرجو التوضيح في ذلك؟","title":"حكم مكث أقارب الميت عند قبره إلى ليلة الجمعة","answer":"الجواب: جلوس بعض أقارب الميت أو غيرهم عند الميت إذا مات في يوم خميس حتى يسلموه ليلة الجمعة هذا لا أصل له، هذا من البدع.\nبل إنما السنة أن يوقف عليه بعد الدفن يدعى له بالمغفرة والثبات، وقفة ما يسر الله من الوقفة، للدعاء له بالمغفرة والثبات ثم ينصرف الناس، سواء كان في يوم الخميس أو في غيره، أما أن يقف عنده أقارب الميت أو جيرانه، إلى ليلة الجمعة أو في بعض الليالي الأخرى وقفات خاصة، هذا لا أصل له إنما الوقفة بعد الدفن للدعاء له وسؤال الله المغفرة والثبات؛ لأن النبي ﷺ إذا فرغ من دفن الميت وقف عليه، النبي عليه الصلاة والسلام: كان إذا فراغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم وسلوا له التثبيت فإنه الآن يسأل.\nفيقف ويستحب للمشيعين إذا فرغوا من الدفن أن يقفوا على الميت، وأن يدعوا له بالمغفرة والثبات ما شاء الله من الوقفة، ولا يلزمهم ولا يشرع لهم أن يقفوا طويلاً كثيراً حتى يسلموه ليلة الجمعة أو في ليالي أخرى بطريقة خاصة لا، إنما هذه وقفة للدعاء بالمغفرة والثبات فقط بعد الدفن، وقفة ليس لها حد محدود، بل وقفة لا تضرهم ولا تشق عليهم ثم ينصرفون.","link":"https://binbaz.org.sa/fatwas/5375/حكم-مكث-اقارب-الميت-عند-قبره-الى-ليلة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":7946,"question":"يقول في سؤاله الثالث والأخير: هل في ذكر مشروع عند الذهاب بالجنازة إلى القبر من تهليل أو تكبير، وماذا يلزم تابع الجنازة والحاملين لها أصلحكم الله ودمتم سالمين؟","title":"حكم التهليل والتكبير أثناء اتباع الجنازة","answer":"الجواب: لا أعلم في هذا شيئاً مشروعاً إلا التفكير والنظر في الموت وعواقب الموت وما بعد الموت، يكون التابع للجنازة يفكر في هذه الأمور وأنه صائر إلى ما صار إليه هذا الميت حتى يعد العدة، أما ما يفعله بعض الناس من قول: اذكروا الله.. وحدوا الله هذا لا أصل له، كان عادة السلف عند اتباع الجنائز الصمت والتفكير والنظر في عواقب الأمور ونهاية الإنسان، وأن منتهاه هو منتهى هذا الرجل الذي هو يتبعه، فهذا يوجب التفكير والنظر والعبرة، وأما الكلام فلا يشرع في هذا كلام فيما أعلم، والذي يفعله بعض الناس من قولهم: وحدوه.. اذكروا الله، هذا كله لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/5472/حكم-التهليل-والتكبير-اثناء-اتباع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06803.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":8465,"question":"يسأل أيضاً سماحة الشيخ ويقول: هل يجوز دفن الميت ليلاً؟","title":"حكم دفن الميت ليلاً","answer":"الجواب: نعم إذا تمكن أهله من الصلاة عليه .. من تكفينه وتغسيله والصلاة عليه فلا بأس، وقد دفن النبي ﷺ بعض الأموات ليلاً، ودفن هو ليلاً عليه الصلاة والسلام، وهكذا الصديق وهكذا عمر دفنا ليلاً وهكذا عثمان .\nفالمقصود أن الدفن في الليل لا بأس به إذا توفرت الأمور المشروعة، إذا تمكن أهله من غسله وتكفينه والصلاة عليه، فلا بأس.\nوأما ما جاء من النهي عن الدفن ليلاً فهذا محمول عند أهل العلم على ما إذا كان الدفن في الليل يفضي إلى عدم أداء الواجب في حق الميت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6472/حكم-دفن-الميت-ليلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12312.mp3","categories":["حمل الميت ودفنه"]},{"id":8466,"question":"هل هناك أوقات نهي للدفن؟","title":"الأوقات المنهي عن الدفن فيها","answer":"الجواب: نعم ثلاث ساعات ثبت عن النبي ﷺ ثلاث ساعات من حديث عقبة بن عامر عند مسلم رحمه الله، قال عقبة بن عامر: ثلاث ساعات نهانا رسول الله ﷺ أن نصلي فيهن وأن نقبر فيهن موتانا: حين تطلع الشمس بازغة حتى ترتفع، وحين يقوم قائم الظهيرة حتىى تزول الشمس، وحين تضيف الشمس للغروب هذه الثلاث: عند طلوع الشمس حتى ترتفع قيد رمح، وعند قيامها قبيل الظهر حتى تزول قبل الظهر بقليل، وعند غروبها عند انحدارها للغروب، وتضيفها للغروب واصفرارها، حينها في هذه الحال لا يصلى على الميت ولا يدفن، يتوقف. نعم.","link":"https://binbaz.org.sa/fatwas/6473/الاوقات-المنهي-عن-الدفن-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12313.mp3","categories":["حمل الميت ودفنه"]},{"id":8600,"question":"أخونا يسأل ويقول: توجد عندنا عاداتٌ قديمةٌ، ولا يزال الكثيرون يتبعون هذه العادات، وهي: الاستغفار والتهليل بالرَّنة والترانيم عند حمل الميت، ويُسمون ذلك: التشهودة، كما يقومون بتلاوة القرآن أثناء دفن الميت، والأذان عليه، وعند الفراغ من دفنه يقوم أحدهم عند رأسه ويقول له -أي: مُخاطبًا للميت-: إذا جاءك كذا فقل كذا.فما رأيكم في ذلك أثابكم الله؟","title":"حكم رفع الصوت في الجنازة، والتلقين والأذان عند الدفن","answer":"الجواب: كل هذه بدعٌ لا أصلَ لها، فالسنة مع الجنازة: التفكير، وخفض الصوت، وتأمل مصير الميت، وماذا يُقال له؟ وماذا يُجيب به؟ وتذكر هذا الأمر العظيم؛ لأنك صائرٌ إلى ما صار إليه.\nفينبغي للمؤمن أن يستشعر هذا الأمر العظيم. وكان السلف رضي الله عنهم يخفضون أصواتهم، ولا يتكلمون برفع الصوت في مثل هذه الحال مع الجنائز، بل يخفضون أصواتهم، ولا يتكلمون إلا بالتفكير والنظر والموعظة، وتذكير الناس بالخير، ودعوتهم إلى الخير. أما \"وحِّدوه\"، أو \"لا إله إلا الله\"، و\"سبحان الله\" بأصواتٍ مرتفعةٍ، هذا لا، غير مشروعٍ، بل هذا بين الإنسان وبين نفسه.\nكذلك الأذان عند القبر: كونه يجلس في نفس القبر، أو عند القبر، أو يُقيم عند القبر، أو في نفس القبر؛ هذا بدعةٌ أيضًا، أو يقرأ فيه القرآن، هذا بدعةٌ، لا أصلَ في ذلك، لا في نفس القبر، ولا عند القبر، كل هذا من البدع. والمقابر ما هي مثل المساجد، يقول النبي ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا؛ دلَّ على أن القبور لا يُصلَّى عندها، ولا يُقرأ عندها، ما هي مثل المساجد.\nكذلك التلقين: كونه يقف عند رأسه بعد الدفن ويقول: قل كذا، قل كذا، إذا سألك الملك عن كذا قل كذا. يُسمونه: التلقين، ويقولون: اذكر ما خرجت عليه من الدنيا؛ أنك تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وأنك ترضى بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ نبيًّا، وبالقرآن إمامًا، إلى غير ذلك مما يقولون؛ هذا لا أصلَ له، جاءت فيه أخبارٌ موضوعةٌ عن النبي ﷺ، لا أصلَ لها، فعله بعض أهل الشام كما ذكره جماعةٌ، ولكن ليس فعلهم بحجةٍ، ولا غيرهم من الناس، الحجة فيما قاله الله ورسوله ﷺ، وفيما أجمع عليه الصحابة، أما قول بعض الناس من المُتأخرين من التابعين، أو أتباع التابعين، إذا اختار شيئًا، أو رأى شيئًا ما يكون حجةً على الناس، ولا يكون دينًا، الدين ما شرعه الله ورسوله ﷺ، وما أمر الله به ورسوله ﷺ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6727/حكم-رفع-الصوت-في-الجنازة-والتلقين-والاذان-عند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12905.mp3","categories":["حمل الميت ودفنه"]},{"id":8790,"question":"السؤال الثاني في رسالة الأخ عباس ، يقول فيه: كانت زوجتي قد اشترت قطعت أرض في المقبرة؛ لتكون هذه القطعة الصغيرة بمثابة قبر لها عند وفاتها، ولكنني لا أرغب أن تفعل هذا أو أدفنها في هذا المكان، وقال الرسول ﷺ: أين ماتوا ادفنوهم فهل هذا الحديث صحيح، وهل علي ذنب في ذلك، أفيدونا أفادكم الله؟","title":"حكم تخصيص المرء أرضاً له ليقبر فيها","answer":"الجواب: أما الحديث هذا فلا أعلم له أصلاً عن النبي ﷺ، ولكن السنة دفن المسلم مع الأموات المسلمين في مقابرهم، وألا يكون في محلٍ شاذ؛ لأن جعله في محل شاذ مستقل قد يفضي إلى الفتنة، وقد يفضي إلى الامتهان بدوسه وإلقاء القمامات عليه ونحو ذلك، فالمشروع أن يكون دفنه مع المسلمين، فإذا كانت الأرض التي اشترتها زوجتك بعيدة عن مقابر المسلمين فالذي ينبغي أن تدفن في مقابر المسلمين إذا ماتت، وهذه الأرض تباع وتصرف قيمتها في مصالح المسلمين، أو في شراء أرض قرب المقبرة حتى تضاف إليها توسعة لها.\nفالحاصل أن هذه الأرض التي اشترتها تريدها مدفناً لها وهي بعيدة عن قبور المسلمين تباع وتصرف قيمتها في أرض جنب المقبرة، توسع المقبرة، أو في حاجات المقبرة من إيجاد محل للبن، أو محل لتغسيل الموتى، أو ما أشبه ذلك، ولا تدفن وحدها.\nأما إذا كانت الأرض تلي المقبرة أو داخلة في المقبرة واشترتها للتوسعة فلا بأس أن تدفن فيها، وليس لك الاعتراض عليها؛ لأن هذا شيء لا بأس به مادامت الأرض تابعة للمقبرة وتلي المقبرة، وداخلة في حساب المقبرة، فلا بأس.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6944/حكم-تخصيص-المرء-ارضا-له-ليقبر-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22007.mp3","categories":["حمل الميت ودفنه"]},{"id":9355,"question":"إذا أوصى الإنسان في حياته بأن يدفن في مكان مخصص فهل تنفذ هذه الوصية، يعني: عند الوفاة يدفن في المكان الذي اختاره قبرًا له؟","title":"حكم الوصية بالدفن في مكان معين","answer":"الجواب: إن كانت البقعة مناسبة كأن يقول: في مقابر المسلمين، أو مع الجماعة في مقبرة الجماعة فلا بأس، أما أن يوصي بمحل خاص في بيته، أو في محل آخر فردًا دون الناس فلا، لا تنفذ له الوصية؛ لأن في بيته خلاف المشروع، وهو وسيلة إلى أن يمتهن أو يغلى فيه، وفي مكان آخر وحده قد يمتهن أو يغلى فيه، ولكن يدفن مع المسلمين في بلاده.\nوإن أوصى بنقله إلى بلاد أخرى فلا يجب التنفيذ لما فيه من الكلفة وعدم الحاجة وعدم المشروعية، بل يدفن في مقبرة بلاده إذا كان في مقبرة للمسلمين يدفن معهم، ولا حاجة إلى نقله إلى محل يكلف مئونة.\nأو يكون في نقله إليه محظور آخر كأن يدفن مع أناس معروفين بالبدعة أو معروفين بالكفر والشر لا يدفن معهم، نقله إلى مقابر المسلمين معروفة في بلده يكفي والحمد لله، ولا حاجة إلى أن يتكلف الورثة نقله إلى بلاد أخرى. نعم.\nالمقدم: في بعض المناطق -سماحة الشيخ- المقابر تمتهن فهي مكان للطرقات وعليها تمر الحيوانات وليس لها صيانة، وليس عليها أسوار ولا ما يشبه ذلك، إذا أوصى الإنسان بأن يدفن بعيدًا عن مثل هذه المقابر كأن يدفن في مزرعة بعيدة عن الطرقات مثلًا، فما رأيكم في مثل هذا؟\nالشيخ: إن تيسر مقبرة يدفن في المقبرة مقبرة المسلمين، أما إذا كان في بر أو في مزرعة بعيدة عن الناس فيدفن في محل خاص من أطراف المقبرة هو ومن يموت من جماعته ومن حوله يقبر حول مزرعة فيكون بعيدًا عن الامتهان، ويكون معروف، يكون قبرًا بارز معروف على طريقة القبور هذا لا بأس به، أما يجعل في مكان يمتهن بالمياه أو بالوطء عليه أو ما أشبه ذلك فلا، لكن متى وجدت مقبرة قريبة منهم نقل إليها، حتى لا يمتهن.\nالمقدم: إذًا إذا طلب الإنسان وهو في حياته أن يكون بعيد عن مثل هذه المقابر فهو محق؟\nالشيخ: أي مقابر؟\nالمقدم: هذه المقابر التي تمتهن وهي طرقات...\nالشيخ: إذا وجد مقبرة غير ممتهنة يدفن فيها، والواجب على أهل البلد أن يصونوا مقابرهم، أن يصونوها بالجدار، أو بشبك من الشوك، أو بشبك من الحديد، أو غيره حتى لا تمتهن، والحكومة وفقها الله قد عمدت البلديات هنا بصيانة المقابر، وهي تصان إذا كتب إليهم في هذا وذكروا صانوها والحمد لله، وإذا تساعد أهل البلد وتعاونوا ولم يحتاجوا لحكومة فهذا خير وأفضل.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7519/حكم-الوصية-بالدفن-في-مكان-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18510.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":10724,"question":"امرأة نصرانية بعلها مسلم توفيت وفي بطنها جنين له سبعة أشهر، هل تدفن مع المسلمين أو مع النصارى ؟","title":"كيفية دفن النصرانية الحامل من زوج مسلم ومكان دفنها","answer":"الجواب: المعروف عند أهل العلم أنها تدفن في محل لا مع الكفار ولا مع المسلمين، تكون في محل خاص؛ لأن بها مسلماً محترماً، فلا يكون مع الكفار، ولأنها كافرة فلا تكون مع المسلمين، ولكن تدفن في محل خاص لا مع هؤلاء ولا مع هؤلاء، ويسوى القبر حتى لا يمتهن في أرض ميتة، ليس فيها قبور للكفار ولا قبور للمسلمين، وتجعل على يسارها حتى يكون وجه الولد إلى القبلة، لأن وجه الولد إلى ظهرها، فيكون وجهه إلى القبلة، حتى لا تكون على جنبها الأيمن؛ لأنه إذا كانت على جنبها الأيمن صار وجهه إلى غير القبلة، فيراعى الولد حتى يكون وجهه إلى القبلة في محل وضعها في قبرها. نعم.","link":"https://binbaz.org.sa/fatwas/8909/كيفية-دفن-النصرانية-الحامل-من-زوج-مسلم-ومكان-دفنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34412.mp3","categories":["حمل الميت ودفنه"]},{"id":10729,"question":"امرأة نصرانية بعلها مسلم توفيت وفي بطنها جنين له سبعة أشهر، هل تدفن مع المسلمين أو مع النصارى ؟","title":"كيفية دفن النصرانية الحامل من زوج مسلم ومكان دفنها","answer":"الجواب: المعروف عند أهل العلم أنها تدفن في محل لا مع الكفار ولا مع المسلمين، تكون في محل خاص؛ لأن بها مسلماً محترماً، فلا يكون مع الكفار، ولأنها كافرة فلا تكون مع المسلمين، ولكن تدفن في محل خاص لا مع هؤلاء ولا مع هؤلاء، ويسوى القبر حتى لا يمتهن في أرض ميتة، ليس فيها قبور للكفار ولا قبور للمسلمين، وتجعل على يسارها حتى يكون وجه الولد إلى القبلة، لأن وجه الولد إلى ظهرها، فيكون وجهه إلى القبلة، حتى لا تكون على جنبها الأيمن؛ لأنه إذا كانت على جنبها الأيمن صار وجهه إلى غير القبلة، فيراعى الولد حتى يكون وجهه إلى القبلة في محل وضعها في قبرها. نعم.","link":"https://binbaz.org.sa/fatwas/8909/كيفية-دفن-النصرانية-الحامل-من-زوج-مسلم-ومكان-دفنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34412.mp3","categories":["حمل الميت ودفنه"]},{"id":11179,"question":"بعد هذا رسالة وصلت إلى البرنامج من الرياض، باعثها المستمع محمد عبد المنعم، يسأل ويقول: هل في الإمكان دفن الأم مع ابنها في قبر واحد؟","title":"حكم دفن أكثر من شخص في قبر واحد","answer":"الجواب:  إذا دعت الحاجة إلى هذا، وإلا فالسنة كل واحد في قبر، لكن لو كان الموتى كثيرين، والمشقة كبيرة جاز جمع الاثنين والثلاثة في قبر واحد، كما فعل النبي يوم أحد عليه الصلاة والسلام، أما إذا كانت الحاجة غير ماسة والأرض موجودة، والدافنون موجودون بدون مشقة كل واحد في قبر، السنة كل ميت في قبر لوحده، هذا السنة، إلا إذا دعت الحاجة الشديدة أو الضرورة إلى دفن الاثنين والثلاثة فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9374/حكم-دفن-اكثر-من-شخص-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37219.mp3","categories":["حمل الميت ودفنه"]},{"id":12002,"question":"يقول: بعد الفراغ من دفن الميت، يقوم أحد أقربائه بقراءة شيء من القرآن على قبره، فهل هذا جائز؟","title":"حكم قراءة القرآن على القبر بعد دفن الميت","answer":"الجواب:  لا، ما له أصل، الدعاء فقط، القرآن ما هو بمشروع، لا يقرأ عند القبور، لكن إذا فرغ؛ يقف عليه ويقول: اللهم اغفر له، اللهم ثبته بالقول الثابت، ونحو ذلك، هو والحاضرون، كان النبي ﷺ إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم، واسألوا لهه التثبيت؛ فإنه الآن يسأل هكذا يقول ﷺ يأمر الناس، يقول: استغفروا لأخيكم، واسألوا له التثبيت؛ فإنه الآن يسأل هذا بعد الدفن، أما قراءة القرآن لا، لا يقرأ عليه القرآن؛ لعدم الدليل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10187/حكم-قراءة-القران-على-القبر-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43116.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":12359,"question":"هل يجوز وضع ميتين في قبر واحد في أي مناسبة؟","title":"هل يجوز وضع ميتين في قبر واحد؟","answer":"الجواب:  إذا أمكن دفنهما في قبرين هذا هو السنة، ويكره دفنهما جميعًا إلا عند الضرورة، كعجزه عن قبرين لخوف، أو لكثرة الموتى، فلا بأس أن يدفنهما جميعًا، كما دفن النبي ﷺ الاثنين والثلاثة يوم أحد بسبب كثرة القتلى، وجراحات الصحابة، أما إذا تيسر لكل واحد في قبر؛ فهذا هو المشروع، ولا يجمعهما جميعًا إلا في حال الضرورة ككثرة الموتى، ومشقة جعل كل واحد في قبر، أو الخوف لو جلس يحفر القبرين، لأسباب تقتضي الخوف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10557/هل-يجوز-وضع-ميتين-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39915.mp3","categories":["حمل الميت ودفنه"]},{"id":12475,"question":"عندما يدفن الميت يقوم أحد الأشخاص بالوقوف أمام القبر، ويدعو بصوت مرتفع، وباقي المشيعين يؤمنون على دعائه، هل هذا جائز، أم هو من المبتدعات؟ جزاكم الله خيرًا.","title":"حكم الدعاء الجماعي بعد الدفن","answer":"الجواب:  لا حرج في ذلك، النبي ﷺ كان إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم، واسألوا له التثبيت؛ فإنه الآن يسأل. فالسنة أن يسألوا كلهم، كل واحد يقول: اللهم اغفر له، اللهم ثبته عند السؤال، اللهم ثبته على الحق، وإذا قال ذلك واحد وأمن الباقون؛ فالحمد لله، لا حرج في ذلك، ولكن الأفضل أن كل واحد يدعو مثلما قال ﷺ: استغفروا لأخيكم كل واحد يقول: اللهم اغفر له، اللهم ثبته على الحق، هذا من حق المسلم على أخيه، ويكفي، والحمد لله، وإن قام واحد، وقال: اللهم اغفر له، اللهم ثبته على الحق، فقالوا: آمين؛ حصل المقصود -إن شاء الله- لكن كون كل واحد يدعو بنفسه، يمتثل الأمر؛ فهذا هو الأفضل. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10686/حكم-الدعاء-الجماعي-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40507.mp3","categories":["حمل الميت ودفنه"]},{"id":12774,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع ياسر محمد العسكري مقيم في المملكة، أخونا يقول: أجيبوني -لو تكرمتم- عن حكم الذي يدفنه أهله في القبور المشيدة وهو غير راضٍ، مع العلم أنه لا يوجد في تلك البلد التي هي بلدته سوى القبور المشيدة؟ جزاكم الله خيرًا.","title":"حكم دفن الميت في مقبرة كل قبورها مشيدة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن الله -جل وعلا- شرع لعباده في الدفن أن يدفن المؤمن في القبر في الأرض، كما قال تعالى: مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ [طه:55] وقال تعالى: ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ [عبس:21] فيحفر له نحو نصف القامة إلى ما يقارب ذلك، ويجعل له اللحد في جهة القبلة، ويوضع في اللحد، ويصف عليه اللبن، ويطين حتى لا يصل إليه التراب، ثم يدفن، ويرفع القبر قدر شبر تقريبًا من تراب القبر، ولا يجوز البناء عليه، لا قبة ولا مسجدًا ولا غير ذلك، ولا يجوز تجصيصه، ولا الكتابة عليه، ولا الزيادة عليه من غير ترابه؛ لأن الرسول ﷺ نهى عن ذلك، قال -عليه الصلاة والسلام-: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك رواه مسلم في الصحيح، وروى مسلم في صحيحه عن جابر  قال: نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه هذا صريح في أنه لا يجوز تجصيصه، ولا البناء عليه، ولا القعود عليه، لكن إذا دفن الإنسان في قبر عليه بناء؛ فالإثم على من فعل، لا عليه هو إذا كان لم يأذن، ولم يرض، إذا دفنه أهله في قبر مشيد، يعني: قد بني عليه، أو جصص عليه؛ يكون الإثم على من فعل، أما هو فلا إثم عليه إذا كان لم يرض، ولم يأذن، وعليه أن يوصي بأن يدفن في المقابر السليمة، عليه أن يوصي، وأن يجتهد أن يدفن في القبور السليمة البعيدة عن البناء عليها، هذا هو الواجب، عليه أن يوصي أهله وقراباته أن يوصيهم، ويحذرهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10988/حكم-دفن-الميت-في-مقبرة-كل-قبورها-مشيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42001.mp3","categories":["حمل الميت ودفنه"]},{"id":13091,"question":"هذا سائل يسأل من فقرتين، يسأل ويقول: ما حكم الدعاء الجماعي عند القبر؟","title":"حكم الدعاء الجماعي عند القبور وعند الدفن","answer":"الجواب:  الدعاء الجماعي عند القبر ليس له أصل، كونه يتعمد يقول: ندعو جميعًا، أنا أدعو وأنتم تؤمنون، هذا ما له أصل، لا نعلم له أصلًا عن السلف الصالح، ولا عن النبي -عليه الصلاة والسلام- لكن لو دعا إنسان، وأمنوا على دعائه من غير قصد، سمعوه يدعو يقول: اللهم اغفر له، وقالوا: آمين، ما فيه شيء، لو دعا إنسان لما دفنوا الميت قال: اللهم اغفر له، اللهم ارحمه، اللهم ثبته بالقول الثابت، فقال بعض الحاضرين: آمين، ما يضر، أما كونهم يتفقون على أن هذا يدعو وهؤلاء يؤمنون هذا لا أصل له ما ينبغي فعله؛ لأن هذا دعاء جماعي مقصود، فلا أصل له، لم يبلغنا عن النبي ﷺ ولا عن الصحابة -رضي الله عنهم وأرضاهم- تركه هو الذي ينبغي.  أما إذا دعا إنسان، سمعوه يدعو، وأمنوا من غير قصد، ومن غير تجمع، ومن غير قصد لهذا الشيء، إنما كانوا يدعون للميت بعدما دفنوه، فأمنوا على دعاء من يدعي، فسمعوا واحدًا يدعو، وقالوا: آمين، آمين، أو دعا هذا، وقال الآخر: آمين؛ لا يضر من غير قصد ومن غير تواطؤ. المقدم: وماذا عن الدعاء بعد دفن الميت جماعة يا شيخ؟ الشيخ: هذا هو، لا، يدعو، كل واحد يدعو لنفسه، كل واحد يقول: اللهم اغفر له، اللهم ارحمه، اللهم ثبته بالقول الثابت، هكذا، ما يحتاج يجتمعون على قول واحد، لكن لو دعا واحد وأمنوا من غير قصد، سمعوه يدعو وقالوا: آمين من غير قصد؛ فلا حرج.","link":"https://binbaz.org.sa/fatwas/11308/حكم-الدعاء-الجماعي-عند-القبور-وعند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50802.mp3","categories":["حمل الميت ودفنه"]},{"id":13120,"question":"يعتقد البعض أن الميت يلقن الحجة، وهي أن يقال له بعد ذهاب الناس، بعد الدفن، ينادى باسمه منسوبًا إلى أمه عند سؤال الملكين قل: كذا وكذا، هل هذا وارد في السنة؟","title":"حكم تلقين الميت بعد دفنه","answer":"الجواب:  هذا ورد في أحاديث ضعيفة، بل موضوعة، وورد عن بعض السلف، لكنه قول ضعيف، غير صحيح، بل هو بدعة، لا يشرع أن يلقن، يروى عن جماعة من أهل الشام من العلماء، ولكنه قول ضعيف، وهذه المسائل لا تقال بالرأي. ولم يثبت عن النبي ﷺ أنه لقن، أو أمر بالتلقين، بل الأحاديث المرفوعة في هذا كلها غير صحيحة، والمشروع ألا يلقن، بل إذا فرغ الناس من دفنه؛ دعوا له بالثبات والمغفرة فقط، كما كان النبي يفعل ﷺ كان إذا فرغ من دفن؛ وقف عليه، وقال: استغفروا لأخيكم واسألوا له التثبيت فإنه الآن يسأل وما كان يلقنه، ما كان يقول له: اذكر ما خرجت من الدنيا أنك تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وأنك رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، وبالقرآن إمامًا، ما كان يفعل هذا، عليه الصلاة والسلام. المقصود: أنه ما كان يلقن الميت، ولا كان أصحابه يلقنون، وإنما كان يدعو له إذا فرغ من دفنه، قال: استغفروا لأخيكم، واسألوا له التثبيت؛ فإنه الآن يسأل هكذا السنة، يقول: اللهم اغفر لفلان، اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم ثبته على الحق، هذا هو المشروع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11343/حكم-تلقين-الميت-بعد-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47315.mp3","categories":["حمل الميت ودفنه"]},{"id":13146,"question":"السائل الذي رمز لاسمه بـ (ع. ع) يقول: هل يجوز الدعاء الجماعي بعد دفن الميت؟","title":"هل يجوز الدعاء الجماعي بعد دفن الميت؟","answer":"الجواب:  أما كون الدافنين الذي يعتمد أحدهم ذلك فيقول: اجتمعوا حتى أدعو وتؤمنوا، هذا لا نعلم له أصلًا، لا أعلم له أصلًا عن السلف الصالح. أما لو دعا على قبر، وقال من حوله: آمين، سمعه يدعو قال: آمين من غير قصد؛ فلا حرج في ذلك، إذا أمن الإنسان على دعاء أخيه عند دفن الميت، اللهم اغفر له، وثبته بالقول الثابت، فقال بعض الحاضرين: آمين آمين؛ فلا بأس، أما قصد ذلك، والاتفاق عليه أن هذا يدعو، وهؤلاء يؤمنون؛ فهذا لا أعلم له أصلًا عن السلف الصالح، فتركه أولى وأحوط. أما إذا أمن من غير قصد، أمن لأنه مشروع أن يدعو للميت، فإذا دعا للميت بعد الدفن، وسمعه بعض إخوانه، وقال: آمين، فلا حرج في ذلك؛ لأنه دعاء بخير، وتأمين على خير، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11400/هل-يجوز-الدعاء-الجماعي-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51006.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":13460,"question":"من أسئلة هذه السائلة من الأردن تقول: رجل أوصى أن يدفن بعد موته في نفس القبر الذي توفيت فيه جدته؛ لأنها كانت محبوبة لديه في حياتها، ويحبها بحجة أن المدة التي مضت على وفاتها فترة طويلة، وأصبح لا وجود للجثة في التربة، فهل تنفذ مثل هذه الوصية؟","title":"هل تنفذ وصية من أوصى بأن يدفن في قبر جدته؟","answer":"الجواب: السنة أن يحفر له قبرًا مستقلًا، ولا تنفذ، يبقى القبر لصاحبه، إلا عند الضرورة، لو كان هناك ضرورة، ضيق في الأرض، والبلد ضيقة ما عندهم مكان، إذا الميت يدفن معه، لكن ما دام ما هناك ضيق؛ فالسنة تبقى القبور على حالها، ويدفن في قبر مستقل، ولو كان يحبها كثيرًا، يدفن في قبر مستقل، هكذا كانت السنة، وهكذا كان الصحابة في عهد النبي ﷺ يدفن كل واحد في قبر على حدة. إنما جمع الاثنين والثلاثة في وقعة أحد لما أصيبوا، وشق عليهم أن يدفن كل واحد على حدة، صار يجمع الاثنين والثلاثة في قبر واحد في وقعة أحد، لكن في وقت السعة لا، كل واحد في قبر واحد، الحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11763/هل-تنفذ-وصية-من-اوصى-بان-يدفن-في-قبر-جدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51708.mp3","categories":["حمل الميت ودفنه"]},{"id":13522,"question":"يقول أخونا: قرأت كتاب رياض الصالحين في باب الدعاء للميت بعد الدفن، والقعود عند قبره ساعة، قال الشافعي -رحمه الله- في هذا الباب: يستحب أن يقرأ عنده شيئًا من القرآن، وإن ختموا القرآن كله؛ كان حسنًا، أرجو من سماحتكم التوجيه النافع لمثل هذا القول؟","title":"حكم قراءة القرآن على القبر بعد دفن الميت","answer":"الجواب: هذا ليس عليه دليل، ولو صح عن الشافعي، إن صح عن الشافعي فليس عليه دليل، والصواب: أنه لا يستحب، والشافعي -رحمه الله- من العلماء المعروفين بالسنة، ولكن كل يخطئ ويصيب، كل عالم له أخطاء، مثلما قال مالك -رحمه الله-: ما منا إلا راد ومردود عليه، إلا صاحب هذا القبر، يعني: النبي ﷺ، والنبي  يقول: كل بني آدم خطاء، وخير الخطائين التوابون. فليس على القراءة عند القبر دليل، والسنة ألا يقرأ عند القبور، ولكن يدعى للميت بعد الدفن، كان -عليه الصلاة والسلام- إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم واسألوا له التثبيت؛ فإنه الآن يسأل ولما زار قبر أمه استأذن ربه أن يستغفر لها، فلم يؤذن له، فجلس عندها، وبكى وأبكى -عليه الصلاة والسلام- لما حصل من المصيبة في عدم إذنه له سبحانه في الاستغفار لها، وكانت ماتت في الجاهلية. ولما حضرت الوفاة عمرو بن العاص  أوصى بنيه ومن يحضر قبره أن يجلسوا عنده قدر جزور، قدر ما تنحر الجزور، ويقسم لحمها؛ كي يستأنس بهم؛ حتى ينظر ماذا يراجع به رسل ربه، وهذا قاله من اجتهاده، وليس في هذا قراءة إنما قصده الدعاء له، والترحم عليه. وسنة الرسول ﷺ بينة في هذا، وهي أنه يدعى له بالمغفرة والثبات، أما كونهم يجلسون قدر ما تنحر جزور، ويقسم لحمها فهذا من اجتهاد عمرو، وليس عليه دليل، إنما المشروع أن يدعى له، ويستغفر له الميت المسلم بعد الدفن، هذا هو المشروع.  أما قراءة القرآن عنده سورة، أو سور، أو ختم القرآن هذا ليس عليه دليل، والذي ينبغي تركه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11841/حكم-قراءة-القران-على-القبر-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47905.mp3","categories":["حمل الميت ودفنه"]},{"id":13611,"question":"سؤاله الثاني يقول سماحة الشيخ: هل يجوز دفن أكثر من جثة في مقبرة واحدة، أفيدونا بذلك؟","title":"حكم دفن أكثر من واحد في قبر واحد","answer":"الجواب: إذا دعت الحاجة إلى ذلك لكثرة الموتى، فلا بأس أن يدفن الاثنان والثلاثة في قبر واحد، النبي ﷺ يوم أحد دفن الاثنين والثلاثة في قبر واحد لكثرة القتلى والمشقة في جعل كل واحد في قبر، فإذا حصل مصيبة، وكثر الموتى؛ فلا مانع أن يدفن الاثنان والثلاثة في قبر واحد، ويقدم الأفضل فالأفضل إلى القبلة، الأفضل والأفضل، يقدم إلى القبلة، كما فعل النبي ﷺ يوم أحد؛ كان يقدم أفضلهم إلى القبلة، أيهم أكثر قرآنًا يقدمه في اللحد. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11951/حكم-دفن-اكثر-من-واحد-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52805.mp3","categories":["حمل الميت ودفنه"]},{"id":14389,"question":"هذا سائل للبرنامج يقول عبدالله أحمد من اليمن: من المعتاد عندنا بأن الناس إذا حملوا الجنازة إلى المقبرة يقومون بذكر: لا إله إلا الله، مكررًا، وبالصوت الجماعي، وعندما يصلون إلى المقبرة يقرؤون سورة يس بصوت جماعي، وجهونا حول هذا العمل من حيث الإجازة، جزاكم الله خيرًا.","title":"حكم رفع الصوت عند الجنازة وقراءة يس أثناء الدفن","answer":"الجواب: رفعهم الصوت عند حملهم الجنازة بصوت جماعي هذا بدعة، ما له أصل، المشروع عند حمل الجنازة الإنسان يتذكر هذا المصير، يتذكر الآخرة والموت، ويكون عنده تذكر وخوف وحذر، أما وحدوه، أو لا إله إلا الله بصوت جماعي هذا بدعة ما له أصل، وهكذا قراءة يس عند القبر بدعة لا أصل لها؛ لأنها تقرأ يس عند المحتضر قبل أن يموت في بيته أو في أي مكان، أما أنها تقرأ في المقابر، أو عند الدفن فهذا بدعة لا أصل له، نعم.","link":"https://binbaz.org.sa/fatwas/12871/حكم-رفع-الصوت-عند-الجنازة-وقراءة-يس-اثناء-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55212.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":14717,"question":"المستمع شعبان محمد عبدالمعطي، يقول: أنا مواطن عربي، ولي سؤال يحيرني دائمًا: أنا مسافر منذ سنتين إلى بلد عربي، وقبل سفري قالت لي أمي: إذا مت وأنت موجود في بلدنا أرجو منك أن تدفني بعيدًا عن أهلك، وشاءت الأقدار أنها توفيت وأنا في السفر، فهل يصح عند عودتي من السفر أن أنقلها إلى مكان آخر؟","title":"حكم نقل الميت بعد دفنه تنفيذًا لوصيته","answer":"الجواب: لا، بل ما دامت دفنت في محل بين المسلمين فلا تنقلها، ولو كنت حاضرًا لم تلزمك هذه الوصية، بل تدفنها في المحل المناسب، ولو كان بخلاف وصيتها؛ لأن الوصية التي تخالف شرع الله لا يلزم تنفيذها، فلو كنت حاضرًا شرع لك دفنها في المحل المناسب بين المسلمين، وإذا كنت غائبًا وقد دفنت في محل بين المسلمين فلا تنقلها.  أما إذا كانت دفنت في محل بين الكفار، أو في محل غير لائق في طريق الناس قد يطؤها الناس، أو في محل عليه خطر من السيل يجرفه، فلا بأس أن تنقلها إلى محل مناسب بين المسلمين من باب الإحسان، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13213/حكم-نقل-الميت-بعد-دفنه-تنفيذا-لوصيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63709.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":14891,"question":"هل يصح الأذان على الميت في القبر أم لا؟ وهل يجوز القنوت بعد دفن الميت؟","title":"حكم الأذان على القبر والقنوت بعد الدفن","answer":"الجواب: كل هذا بدعة، لا يؤذن في القبر، ولا يقنت قنوت الدعاء المعروف، ولكن يدعى له دعاء، الدعاء العادي، إذا فرغوا من الدفن يسألوا الله له التثبيت والمغفرة.  أما القنوت مثل قنوت الصلاة لا، ولكن كل واحد يدعو لأخيه «كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم، واسألوا له التثبيت فإنه الآن يسأل فيقول: اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم ثبته على الحق، ولا يقنت قنوت الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13388/حكم-الاذان-على-القبر-والقنوت-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63908.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":15371,"question":"بالنسبة لكشف وجه الميت إذا وضع في قبره؟","title":"حكم كشف وجه الميت عند وضعه في القبر","answer":"الجواب: المشروع أن يغطى وجهه، وجميع بدنه، الميت إذا وضع في القبر لا يكشف منه شيء، بل يكون الكفن شاملًا له كله، من رأسه إلى رجليه، هذا هو السنة، هذا هو الذي فعله النبي ﷺ وأرشد إليه، فلا يكشف وجهه، وما يظن بعض العامة أنه يكشف وجهه غلط، الواجب أنه يغطى كله، إلا إذا كان محرمًا، مات وهو محرم، فإنه لا يغطى رأسه، ولا وجهه؛ لأن النبي ﷺ لما مات رجل في إحرامه، قال ﷺ: كفنوه في ثوبيه، ولا تخمروا رأسه، ولا وجهه، فإنه يبعث يوم القيامة ملبيًا. فالمحرم إذا مات وهو محرم لا يغطى رأسه ولا وجهه، إلا إذا كان امرأة يغطى رأسها ووجهها؛ لأن المحرمة لا بأس أن تغطي وجهها وإن كانت محرمة، المرأة لا بأس، أما الرجل فلا، إذا كان محرمًا ومات فإنه يغسل ويكفن، ولكن لا يغطى وجهه ولا رأسه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13874/حكم-كشف-وجه-الميت-عند-وضعه-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56702.mp3","categories":["حمل الميت ودفنه"]},{"id":15456,"question":"هذا سؤال من المستمع محمد يونس عطا، من جمهورية مصر العربية، يقول: توفي والدي وأنا لا أزال صغيرًا، فدفن في مقبرة لعمي، وبعد مضي عدة سنوات حصل بيني وبين عمي نزاع، فقال لي: أخرج والدك من مقبرتي، وهددني بسوء إن لم أفعل، فلم أجد حلًا إلا أن أجبت طلبه، ونقلت جثمان والدي إلى مقبرة تخصني، فهل علي إثم في ذلك؟ وهل المقابر ملك للأحياء، يتصرفون فيها كيف شاؤوا، أم أنها ملك لساكنيها؟أفيدونا، بارك الله فيكم.","title":"حكم نقل الميت إلى قبر آخر للحاجة والتحكم في المقابر","answer":"الجواب: نقله لهذه الحاجة لا بأس، نقل أبيك من مقبرة إلى مقبرة دفعًا للشر والفتنة، لا بأس عليك، ولا حرج في ذلك، والحمد لله. أما المقابر تختلف، فإذا كان الذي سبلها أرادها لقوم معينين، فليس لغيرهم أن يدفنوا فيها إلا بإذنه، إذا كان عينها لقرابته أو لجيرانه أو لقبيلة معينة فليس لغيرهم الدفن فيها إلا بإذنه. أما إذا كان أرادها للمسلمين عمومًا له ولجيرانه والمسلمين إذا كان ما أراد جماعةً معينة، فلا مانع أن يدفن فيها غير من أراد من قرابته، إذا كان ما أرادها لأحد معين، وإنما سبلها للمسلمين، فلا مانع من القبر فيها، والدفن فيها لكل أحد. وما دام هددك وشدد عليك حتى تخرج أباك، فلا بأس عليك، واتقاء الفتنة مطلوب، ودفع الشر مطلوب، ونقله في مثل هذه الحال لا حرج فيه -إن شاء الله-؛ لما في هذا من دفع الحرج، ودفع الفتنة والشر، نعم.\nالمقدم: لكن هذا الشخص أليس آثمًا بفعله ذا بعد موافقته على دفنه؟\nالشيخ: هذا لا يجوز، هذا لا يجوز، الذي أمره لا يجوز له هذا العمل، ما دام أذن في دفنه في أرضه ومقبرته، ليس له بعد هذا أن يرجع، بل هو آثم في هذا الأمر ومخطئ، نعم، خاطئ في هذا الأمر، نعم.","link":"https://binbaz.org.sa/fatwas/13984/حكم-نقل-الميت-الى-قبر-اخر-للحاجة-والتحكم-في-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68704.mp3","categories":["حمل الميت ودفنه"]},{"id":15457,"question":"سؤاله الآخر يقول: هل يصح أن يوصي الميت في حياته بدفنه في المكان الفلاني، أو إلى جانب الشخص الفلاني؟ وإن حصل شيء من ذلك فهل على أهله تنفيذ طلبه في دفنه حيث أوصى؟","title":"حكم الوصية بالدفن في مكان معين، وحكم تنفيذها","answer":"الجواب: لا بأس أن يوصي أن يدفن في المقبرة الفلانية، أو بجوار فلان؛ لأنه قد يكون له قصد في ذلك؛ لأنهم من الصلحاء والأخيار، فلا بأس أن يدفن مع الصلحاء والأخيار، وإن أوصى بذلك فلا بأس، وعلى الوصي أن ينفذ هذه الوصية إذا استطاع تنفيذها إذا تيسر تنفيذها.  أما إذا لم يتيسر تنفيذها؛ لعجزه عن ذلك، أو لبعد المسافة، أو ما أشبه ذلك، فلا حاجة إلى التنفيذ، ويدفن في أي مقبرة من مقابر المسلمين، والحمد لله. وإذا كانت المقبرة بعيدة من بلد إلى بلد فلا وجه لهذه الوصية، ولا حاجة إلى تنفيذها، بل يدفن في مقبرة بلده إذا كانت مسلمة، أو في مقبرة أخرى من قبور المسلمين، ويكفي، ولا حاجة إلى أن يتكلفوا من التركة أموالًا لنقله بالطائرات أو غيرها، هذا لا حاجة إليه، ما دام يوجد مقبرة مسلم يدفن فيها، فالحمد لله، ولا حاجة إلى تنفيذ هذه الوصية؛ لأنها وصية لا وجه لها شرعًا. أما إذا كان الدفن في المقبرة التي أراد متيسر في جانب البلد في طرف البلد؛ لأن البلد فيها مقابر، واختار واحدة منها، فالأمر في هذا واسع، والتنفيذ أولى، نعم. المقدم: حتى لو اختار في نفس القبر، يعني: يدفن مع شخص آخر في قبر .\nالشيخ: أجل بجواره، لا بأس بجواره. المقدم: بجواره؟\nالشيخ: نعم، إذا تيسر. المقدم: نعم؟ الشيخ: إذا تيسر هذا أولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13986/حكم-الوصية-بالدفن-في-مكان-معين-وحكم-تنفيذها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68705.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":15674,"question":"من رأس المعرة في الجمهورية العربية السورية رسالةٌ بعثها مستمعٌ، يقول السائل رفاعي: عندنا عادةً يسير مع الجنازة الناس أثناء تشييعها إلى المقبرة، ثم يُرددون كلمة: \"لا إله إلا الله، محمدٌ رسول الله ﷺ\" بصوتٍ عالٍ ومرتفعٍ، فهل ورد هذا عن الرسول ﷺ، أو أنه بدعةٌ مُحرمةٌ؟جزاكم الله خيرًا.","title":"حكم رفع الصوت بالذكر عند تشييع الجنازة","answer":"الجواب: هذا بدعةٌ، ما له أصلٌ، كان السلف إذا كانوا مع الجنائز يغضون أصواتهم، يتأملون حال الموت وما بعد الموت، يتذكر الإنسان هذه الأمور العظيمة، أما رفع الصوت بالأذكار مع الجنازة فلا أصلَ له، بل هو من البدع، لكن إذا دُفن الميت، وفرغوا من دفنه، يُشرع الدعاء له؛ كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه وقال: استغفروا لأخيكم، وسلوا له التثبيت، فإنه الآن يُسأل. فالسنة الدعاء للميت: اللهم اغفر له، اللهم ثبته بالقول الثابت. بعد الفراغ من دفنه، اللهم اغفر له، اللهم ثبته بالقول الثابت، اللهم أدخله الجنة، ونجِّه من النار. لا بأس، كله طيبٌ، الرسول ﷺ قال: استغفروا لأخيكم، وسلوا له التثبيت، فإذا سأل له المغفرة والثبات هذا طيبٌ، بعد الدفن، أما رفع الأصوات مع الجنازة، أو عند الدفن على طريقةٍ خاصةٍ: \"لا إله إلا الله، محمدٌ رسول الله\"؛ هذا ما له أصلٌ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14218/حكم-رفع-الصوت-بالذكر-عند-تشييع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70605.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":16032,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المغرب باعثها أحد الإخوة من هناك يقول، شاب يسأل من المغرب، أخونا يقول: توفي رجل، ثم قام الناس بتشيعيه، وهم يقولون: لا إله إلا الله، محمد رسول الله، وبصوت مسموع، ومرتفع، ثم قام أهل الميت بالصدقة عليه، وعندما رجع الناس من دفنه بدؤوا في الأكل والشرب والضحك فيما بينهم، ما رأي سماحتكم في مثل هذه التصرفات؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت عند تشييع الجنازة والضحك وصنع الطعام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فاتباع الجنازة، ورفع الأصوات بالذكر، أو الصلاة على النبي ﷺ لا أعلم له أصلًا في الشرع، بل السنة خفض الصوت في هذه الحالة، وأن الإنسان يحاسب نفسه، ويتذكر مصير هذا الميت، ومصيره هو أيضًا؛ لأن الموت له شأن عظيم، وذكره يحرك القلب إلى الاستعداد للقاء الله، والقيام بحقه، والحذر من معاصيه . فالمسنون لأتباع الجنازة أن يتأملوا مصير هذا الميت ومصيرهم، وأن يعدوا العدة، وأن يخفضوا الأصوات؛ تقديرًا لهول الموقف، وشدة الحاجة إلى الإعداد للآخرة، والتأهب للموت قبل نزوله. وأما صنع الطعام من أهل الميت فهذا فيه تفصيل: أما صنع الطعام من أجل المصيبة، وجمع الناس هذا ليس من المشروع، بل من عمل الجاهلية، أما إذا صنعوه لأجل ضيف نزل بهم، أو لأنفسهم فلا بأس، أو جاءهم طعام من غيرهم، فإنه يسن لجيرانهم وأقاربهم أن يصنعوا لهم طعامًا؛ لأنه قد أتاهم ما يشغلهم، لما ثبت عن النبي ﷺ أنه أمر أهله أن يصنعوا طعامًا لأهل جعفر لما قتل في مؤتة، لما جاء خبره إلى المدينة  جعفر بن أبي طالب، أمر أهله أن يصنعوا لأهل جعفر طعامًا، وقال: إنه قد أتاهم ما يشغلهم. فإذا صنع أقارب الميت لأهل الميت طعامًا، أو جيرانه؛ فهذا مشروع، وإذا دعا أهل الميت من يأكل معهم من.. الطعام، أو قدموه.. لضيفانهم كل هذا لا بأس به. أما رجوعهم بعد الدفن للضحك، واللعب؛ هذا ليس بالمناسب، بل الأفضل لهم أن يتدبروا الأمر، ويظهر عليهم أمارات الحزن والاستعداد، ولهذا لما مات إبراهيم بن النبي ﷺ قال -عليه الصلاة والسلام-: العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي الرب، وإن بك يا إبراهيم ! لمحزونون. ولما حضر الموت ابن بنته -عليه الصلاة والسلام- دعته ﷺ .... حضر، فلما رأى نفس الصبي تقعقع عند الخروج؛ بكى، فسأله بعض الحاضرين عن ذلك، فقال: إنها رحمة، وإنما يرحم الله من عباده الرحماء. فالأفضل لأهل الميت أن لا يشتغلوا بالضحك واللعب، بل يقدروا الموقف، ويظهر عليهم آثار الحزن مع الرضا عن الله، والاسترجاع: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:156] والصبر والاحتساب، أما مقابلة ذلك بالضحك، واللعب فليس من المشروع، وليس من المناسب، بل المناسب إظهار الحزن، وإظهار الدعاء للميت، والاستغفار له، وعدم إظهار اللعب، والضحك، ونحو ذلك مما يدل على عدم المبالاة، وفي التأسي بالنبي ﷺ الخير والبركة، فما كان ﷺ عند الموت يظهر الضحك، بل كان يظهر الحزن والبكاء ويقول: إنها رحمة وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14669/حكم-رفع-الصوت-عند-تشييع-الجنازة-والضحك-وصنع-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71101.mp3","categories":["حمل الميت ودفنه","أحكام التعزية","البدع والمحدثات"]},{"id":16147,"question":"يقول أخونا: إنه حين يدفن الميت في المقبرة يأتي أناسًا، ويقرؤون على قبر الميت سورة يس وقل هو الله أحد فهل هذا جائز؟","title":"حكم قراءة يس والإخلاص عند دفن الميت","answer":"الجواب: ليس بجائز، إنما تقرأ يس عند المحتضر قبل أن يموت، أما على قبره لا تقرأ يس، ولا غيرها، ولكن يدعى له بعد الدفن، وعند الزيارة، يدعى له بالمغفرة والرحمة، والنجاة من النار، أما أن يقرأ على الميت على قبره يس، أو غيرها هذا غير مشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14815/حكم-قراءة-يس-والاخلاص-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75005.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":16153,"question":"يقول: في بلادنا ندفن الموتى مع بعضهم من كان يصلي، ومن لم يكن يصلي، فما هو توجيهكم؟","title":"حكم دفن تارك الصلاة في مقابر المسلمين","answer":"الجواب: الواجب أن تكون المقبرة خاصة بالمسلمين، وإذا عرف أن الرجل لا يصلي؛ يدفن في محل آخر، غير مقبرة المسلمين، هذا هو الأرجح، في محل بعيد، وإن ووسي في أرض ميتة حتى لا يعرف؛ فلا بأس، مثل الكافر المعروف النصراني واليهودي والشيوعي يدفنوا في محل بعيد عن مقبرة المسلمين، في أرض ميتة، بعيدة، وتواسى عليهم الأرض؛ حتى لا تعرف قبورهم، ويستراح منهم؛ حتى لا يتأذى الناس وجيفهم.  وقال جمع من أهل العلم: إنه إذا كان لا يصلي، ولكنه يقر بأنها واجبة، وفريضة أنه لا يكفر بذلك، وأنه يدفن مع المسلمين، هذا قاله جماعة من أهل العلم، وذكره بعض أهل العلم أنه قول الأكثرين، فإذا دفنوه مع المسلمين بفتوى أحد من العلماء؛ فلا بأس. وإلا فالأصوب والأصح أن تارك الصلاة كافر كفرًا أكبر، هذا هو الأصح لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. ولما سئل -عليه الصلاة والسلام- عن الأئمة الذين يخرج عليهم؛ لأنهم أتوا كفرًا بواحًا، قال في حقهم: لا تخرجوا عليهم -معناه- ما أقاموا فيكم الصلاة لما سألوه: «هل نقاتلهم قال: لا. ما أقاموا فيكم الصلاة فدل على أن ترك الصلاة من الكفر البواح، نسأل الله العافية. فنسأل الله لجميع المسلمين، ولجميع الضالين والكافرين التوفيق للتوبة، نسأل الله أن يمن عليهم بالتوبة النصوح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14821/حكم-دفن-تارك-الصلاة-في-مقابر-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75007.mp3","categories":["حمل الميت ودفنه"]},{"id":16383,"question":"من الهند حيدر أباد رسالة بعث بها المستمع صالح علي باللفقع، أخونا صالح له جمع من الأسئلة يقول في أحدها: عندنا إذا مات الميت، وأثناء وجوده في البيت، وعندما يجيء أحد في العزاء يقوم أحد الحاضرين بكشف وجه الميت، وبعدما يغسل، ويصلى عليه في المسجد يقوم أحد أقاربه بفك الغطاء عن وجه الميت بذكر الصلاة على محمد ﷺ ثم يقوم الحاضرون جميعًا بما يسمونه نظرة الوداع، فما هو رأيكم في هذا العمل؟ جزاكم الله خيرًا.","title":"حكم كشف وجه الميت بعد الصلاة عليه","answer":"الجواب: هذا لا أصل له، أقول: ليس له أصل هذا، والسنة أن يدفن مغطى الكفن كله، وجهه وغير وجهه، السنة أن يكون الكفن عامًا، وأن لا يكشف وجهه ولا غيره، أما ما دام بينهم فكشفوه ليسلم عليه من هو من محارمه إن كان زوجته، أو أخواته، أو يسلم عليه الرجل إذا كان رجلًا؛ فلا بأس، أو امرأة يسلم عليها محارمها، أو زوجها لا حرج في ذلك، النبي ﷺ لما توفي وجاء الصديق من منزله كشف وجهه وقبله، وقال: «طبت بأبي أنت وأمي حيًّا وميتًا» عليه الصلاة والسلام. فإذا كشف لمصلحة تقبيله، أو النظر إليه، والدعاء له؛ فلا حرج في ذلك، لكن عند وضعه في القبر لا يكشف وجهه، بل يكون مغطى الوجه، وجميع البدن في القبر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15091/حكم-كشف-وجه-الميت-بعد-الصلاة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75413.mp3","categories":["حمل الميت ودفنه"]},{"id":16384,"question":"هل يلقى الميت في القبر على ظهره، أو على جنبه الأيمن متجهًا إلى القبلة؛ لأني أرى الناس عندنا يطرحون الميت على ظهره، وبعد الأربعين من موت الميت يقوم أقاربه بإلقاء عزيمة كبيرة، ويسمونها الفاتحة، ما هو رأيكم فيما يفعله الناس؟","title":"كيفية وضع الميت في القبر وحكم العزومة بعد الموت","answer":"الجواب: السنة أن يوضع على جنبه الأيمن موجهًا إلى القبلة، هذا هو السنة، فإن الكعبة هي قبلة المسلمين أحياء وأمواتا، وأما هذه العزيمة فلا أصل لها، بل هي بدعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15092/كيفية-وضع-الميت-في-القبر-وحكم-العزومة-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75414.mp3","categories":["حمل الميت ودفنه","أحكام التعزية"]},{"id":16390,"question":"يضعون أيضًا الورود على النعش وهم يحملون الميت إلى المقبرة، ويقولون بصوت عال: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر؟","title":"حكم وضع الورود على النعش ورفع الصوت بالتهليل عند التشييع","answer":"الجواب: كل هذا لا أصل له، وضع الورود على النعش، وعلى الميت كل هذا لا أصل له، إنما السنة تطييبه، بعدما يغسل يطيب، ويكفن، هذا السنة، أما طرح الأوراد، أو الأطياب على النعش، أو كذا، هذا لا أصل له. كذلك رفع الصوت بالتسبيح، أو بالتهليل، أو بالتحميد، أو بالتكبير لا أصل له، بل السنة في هذا المقام خفض الصوت، والإقبال على محاسبة النفس، والتفكير في الموت، وما بعده، حتى يعد العدة لهذا الأمر العظيم الذي وقع بهذا الحاضر، فالذي وقع به سوف يقع بغيره، فالسنة خفض الأصوات في هذه الحال مع الجنائز، وعدم رفع الأصوات مع الجنازة عند السير بها إلى الصلاة، أو إلى الدفن، أما ما يفعله بعض الناس: سبحوه، أو وحدوه، أو اذكروا الله؛ هذا ليس له أصل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15095/حكم-وضع-الورود-على-النعش-ورفع-الصوت-بالتهليل-عند-التشييع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75416.mp3","categories":["حمل الميت ودفنه"]},{"id":16597,"question":"المستمع معيض عبدالله الشهري من الرياض بعث يسأل ويقول: يوجد لدينا محل الأموات على شكل غرفة تحت الأرض، حيث يوضع الميت، وبعد سنة يفتح هذا القبر، ويوضع ميت آخر، فهل يعذب المذنب، ويؤذي المحسن في قبر واحد؟ جزاكم الله خيرًا.","title":"هل يتأذى المحسن بعذاب المسيء إذا كانا في قبر واحد؟","answer":"الجواب: السنة أن يقبر كل إنسان على حدة مع القدرة إذا اتسعت الأرض، وأمكن قبر كل واحد على حدة، فهذا هو السنة كما كان النبي ﷺ في البقيع يقبرون الموتى، هكذا كل واحد على حدة، أما إذا حصل ضرورة، ولم يوجد مكان إلا هكذا فلا حرج، وكل يؤخذ بذنبه، المحسن يجازى بإحسانه، والمسيء يجازى بإساءته وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]. لكن مهما أمكن فالمشروع أن يدفن كل واحد على حدة، كل قبر على حدة، ولا يجمعون في محل واحد، نسأل الله السلامة والعافية.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15327/هل-يتاذى-المحسن-بعذاب-المسيء-اذا-كانا-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81709.mp3","categories":["حمل الميت ودفنه"]},{"id":16611,"question":"مستمع آخر يسأل عما يحدث في الجنائز -سماحة الشيخ- ويبدو أنها بلية منتشرة في كثير من الأقطار، فهذا يسأل ويقول: أثناء تشييع جنازة متوفى، أجد بعض الناس يقولون: (لا إله إلا الله) بصوت مرتفع، وأجد بعضهم يقول: (اذكروا الله) ما حكم هذا العمل؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت بالذكر عند تشييع الجنازة","answer":"الجواب: ليس عليه دليل، السنة في هذا كان السلف إذا اتبعوا جنازة يسرون، ويخشعون، ويتذكرون الموت، وما بعده، فالسنة في مثل هذا عدم الكلام، والتفكر في المصير، وما يكون بعد الموت، وكيف يسأل الميت في قبره، حتى يكون الإنسان متأثرًا بهذا المحضر، أما أن يقول: اذكروا الله، أو وحدوا الله، أو قولوا: لا إله إلا الله؛ هذا لا دليل عليه؛ فينبغي تركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15345/حكم-رفع-الصوت-بالذكر-عند-تشييع-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75815.mp3","categories":["حمل الميت ودفنه"]},{"id":16617,"question":"يقول: شاعت ظاهرة حمل الميت في سيارة، وعليها مكبر للصوت، ويوضع شريط قرآن، حتى يصلوا بالميت إلى المقبرة، وأيضًا في الأعياد نجد الناس يذهبون إلى المقبرة، ومعهم تسجيل، ويفتح على القبر معتقدين هذا العمل بأنه ينفع الميت، ما حكم هذه الأفعال؟ جزاكم الله خيرًا.","title":"حكم حمل الجنازة على السيارة وفتح مكبرات الصوت بالقرآن","answer":"الجواب: هذا لا أصل له، كونه يضع مكبرًا على السيارة التي فيها الجنازة، ويقرأ القرآن، أو يذهب بالمسجل، ويقرأ القرآن عند القبور، فهذا بدعة لا أصل لها، ولا ينبغي فعل ذلك، ولم يشرع الله القراءة عند القبور، ولا الدعاء عندها يتحرى هذا، إنما يدعو في أثناء الزيارة حين يسلم عليهم، يدعو لهم، ولنفسه كما فعله النبي ﷺ وأرشد الأمة إلى ذلك، كان يقول ﷺ إذا زار القبور: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، غدًا مؤجلون، يغفر الله لنا ولكم، اللهم اغفر لأهل بقيع الغرقد وكان يعلم أصحابه  إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هكذا يشرع عند زيارة القبور، الدعاء لهم، وللزائر. أما قراءة القرآن، أو الصلاة عند القبر، أو الجلوس عنده يتحرى الدعاء عنده؛ هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15347/حكم-حمل-الجنازة-على-السيارة-وفتح-مكبرات-الصوت-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75817.mp3","categories":["حمل الميت ودفنه"]},{"id":16709,"question":"المستمع علي حسين الصالح عثيمان البابكري بعث برسالة وضمنها جمعًا من الأسئلة في أحد أسئلته يقول: هل يجوز رفع الصوت أثناء حمل الجنازة؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت أثناء حمل الجنازة","answer":"الجواب: لا، السنة السر في .... وخفض الصوت، ويتذكر الإنسان المصير، وأنه سوف يصيبه ما أصاب هذه الجنازة، يتذكر الموت، وما بعده، أما ما يفعله بعض الناس: وحدوه وحدوه واذكروا الله، هذا ما عليه دليل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15454/حكم-رفع-الصوت-اثناء-حمل-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76104.mp3","categories":["حمل الميت ودفنه"]},{"id":17161,"question":"السائل أحمد سالم استعرضنا بعضًا من أسئلته بقي له هذا السؤال، يقول: عند تشييع الجنازة يا شيخ إلى المقبرة يرددون أذكارًا بصوت جماعي، مثل: لا إله إلا الله محمد رسول الله.. وغير ذلك، وعندما يدخل الميت في القبر يؤذنون ويقيمون، وبعد الدفن يلقنونه، أي: يقولون: يا فلان ابن فلان قل: لا إله إلا الله، قل: ربي الله، وديني الإسلام، ونبيي محمد ﷺ ما رأيكم في مثل هذا العمل؟","title":"حكم رفع الصوت في الجنازة والأذان عند الدفن","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا العمل كله بدعة لا يجوز، رفع الأصوات مع الجنائز ووحدوه، أو لا إله إلا الله، كلها بدعة، السنة مع الجنائز التدبر، والتأمل، والخشوع، وتذكر الموت، والدعاء للميت، أما رفع الأصوات بالأذكار أو وحدوه، كل هذا لا أصل له.  وهكذا الأذان في القبر، أو الإقامة في القبر كله بدعة، وهكذا التلقين، يا فلان اذكر ما خرجت له من الدنيا، كله بدعة، والأحاديث في التلقين كلها غير صحيحة، غير ثابتة عن النبي ﷺ فهذا كله بدع، لا يلقن، ولا ينفعه التلقين، ما ينفعه إلا عمله السابق قبل الموت، أما بعد الموت لا ينفعه، وهكذا الأذان في قبره، أو الإقامة في قبره، أو القراءة، كله بدعة لا تجوز. نعم.","link":"https://binbaz.org.sa/fatwas/15979/حكم-رفع-الصوت-في-الجنازة-والاذان-عند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59001.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":17492,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من سلطنة عمان، باعثها أحد الإخوة المستمعين، يقول: (ح. س. م)، أخونا له رسالة ضمنها ثمان قضايا، في إحداها يقول: قد نعيش ظاهرةً غريبة بعد دفن الميت، وهي ظاهرة تلقين الميت بعد أن يدفن، حيث يقوم الخطيب، أو الإمام بقراءة بعضٍ من آيات الذكر الحكيم، ثم يتلوها بوصية للميت، ومن بين الكلام الذي يخطب به الميت، يقول: يا عبد الله، لا تنس العهد الذي بيننا وبينك، والذي عشت عليه، إن دينك الإسلام، ونبيك محمد ﷺ، ولا تجزع من الملكين، فهم عباد الله.. إلى آخر مثل ذلك،  هل ذلك ورد عنه ﷺ أو عن صحابته؟ أرجو من سماحتكم توضيح ذلك، مع ذكر الدليل من السنة إن ورد عن رسول الله ﷺ؟ جزاكم الله خيرًا.","title":"حكم تلقين الميت بعد دفنه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد:\nفالتلقين للميت بعد الدفن لم يثبت عن النبي ﷺ، ولا عن أصحابه ، وإنما ورد في حديثٍ موضوع، رواه الطبراني من حديث أبي أمامة الباهلي، وهو ليس بثابت، وليس بصحيح، بل هو موضوع، ويروى عن جماعة من أهل الشام فعل ذلك، والصواب أنه بدعة، لا يشرع، والميت على ما مات عليه، وإنما التلقين قبل خروج الروح، يقول النبي ﷺ: لقنوا موتاكم: لا إله إلا الله، يعني: المحتضرين، يلقن قبل أن يموت هذه الكلمة العظيمة، وهي: (لا إله إلا الله)؛ لأنه ﷺ قال: من كان آخر كلامه:لا إله إلا الله، دخل الجنة فإذا قالها عن صدق، وعن إخلاص، وإيمان بما دلت عليه من توحيد الله والإخلاص له، والبراءة من الشرك وأهله، فإن الله جل وعلا يجعل ذلك من أسباب نجاته وسعادته، إذا لم يكن مصرًا على شيء من الكبائر، وإلا فهو تحت مشيئة الله، من مات على المعاصي فهو تحت مشيئة الله، إن شاء غفر له، وإن شاء عذبه على قدر المعاصي التي مات عليها. ثم بعد التطهير في النار يخرجه الله من النار إلى الجنة إذا كان مات على التوحيد، عند أهل السنة والجماعة، هذا هو الحق، خلافًا للمعتزلة ومن سار على نهجهم، وخلافًا للخوارج؛ فإنهم يقولون: إنه مخلدٌ في النار -العاصي- والخوارج تكفره بذلك، والذي عليه أهل السنة والجماعة وهم أصحاب النبي ﷺ وأتباعهم بإحسان، أن من مات على التوحيد وعنده معاصي لا يكفر عندهم، ولا يخلد في النار إن دخل النار، بل هو تحت مشيئة الله، إن شاء الله جل وعلا غفر له، وعفا عنه بتوحيده، وإيمانه، وأعماله الصالحة، وإن شاء سبحانه عذبه على قدر المعاصي التي مات عليها من الكبائر، من الزنا، أو السرقة، أو عقوق الوالدين، أو قطيعة الرحم، أو أكل الربا، أو نحو ذلك من الكبائر، لقول الله  في كتابه العظيم في آيتين من سورة النساء، يقول سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. فأخبر سبحانه أنه لا يغفر لمن مات على الشرك، وأنه يغفر ما دون ذلك لما دون الشرك، لمن يشاء، فدل ذلك على أنه ليس بكافر؛ لأن العاصي الذي مات على شيء من الكبائر ليس بكافر، إذا مات موحدًا مسلمًا، فإذا مات على الزنا، ما تاب من الزنا، أو عقوق الوالدين، أو أحدهما، أو أكل الربا، لم يتب، ولم يستحل ذلك، فهو تحت مشيئة الله، وهكذا صاحب الغيبة والنميمة، وما أشبهه من المعاصي، هو تحت مشيئة الله ، عند أهل الحق، عند أهل السنة والجماعة، خلافًا للخوارج والمعتزلة، ومن سار على نهجهم، للآية الكريمة ولأنه ثبت بالتواتر، عن النبي ﷺ أنه يشفع يوم القيامة لمن دخل النار من المسلمين وهو على التوحيد، فيحد الله له حدًا، فيخرجه من النار، ثم يشفع، ثم يشفع، ثم يشفع، كلما شفع حد الله له حدًا فأخرجه من النار. وهكذا يشفع النبيون، والملائكة، والمؤمنون، والأفراط، ويبقى بقية من أهل التوحيد في النار، يخرجهم الله سبحانه من النار، بفضل رحمته جل وعلا، بعدما جرى تعذيبهم فيها المدة التي شاءها الله ، هذا هو الحق الذي لا ريب فيه، وهو الذي عليه أهل السنة والجماعة من أصحاب النبي ﷺ ومن بعدهم.\nأما التلقين بعد الدفن، هو بدعة، كونه يقف عند القبر عند رأسه ويقول: اذكر كذا.. اذكر كذا هذا لا أصل له في الشرع، وإنما هو من فعل بعض العلماء، ولم يفعله النبي ﷺ ولا أصحابه رضي الله عنهم وأرضاهم. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16402/حكم-تلقين-الميت-بعد-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72601.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":17918,"question":"يقول السائل: بعض الناس أثناء الدفن - دفن الميت - يقولون بعض الكلمات مثل: قراءة الفاتحة، وبعضهم يقول: صلوا على محمد ﷺ، نرجو توضيح السنة في هذا الأمر؟","title":"حكم قراءة الفاتحة والصلاة على النبي ﷺ أثناء دفن الميت","answer":"الجواب: هذا بدعة، كونه يقول لهم: اقرءوا الفاتحة، أو يقرأها عند الدفن هذا بدعة، وإنما يقول عند الدفن: باسم الله وعلى ملة رسول الله. أو يقول: صلوا على النبي، يرى أن هذا قربة في هذا المكان ما يصلح؛ لأن تخصيص بقعة بأن يقال فيها: صلوا على النبي أو عند عمل خاص بغير دليل يكون بدعة. أما تذكيرهم بأن يقول: اتقوا الله، تذكروا الموت، أعدوا للآخرة، النبي ﷺ ذكر أصحابه عند الدفن وهو جالس عند القبر قبل أن يلحد جاء في حديث البراء بن عازب وحديث علي أنه كان جالس عند القبر قبل أن يلحد ينتظر لحده وكان يعظهم ويذكرهم عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/16948/حكم-قراءة-الفاتحة-والصلاة-على-النبي-ﷺ-اثناء-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78012.mp3","categories":["حمل الميت ودفنه","البدع والمحدثات"]},{"id":18236,"question":"يقول سماحة الشيخ هذا السائل: بعض الناس يقول: جرت العادة في بلدي بأنهم يمشون بالجنازة وهم يرددون: لا إله إلا الله، ثم جاء البعض من الناس وقالوا: بأن هذا بدعة، فيقومون بأخذ الجنازة من المسجد ويذهبون بها حتى القبر ويدعون أو يدعون بالحديث «عجلوا بموتاكم»، علمًا أن مع الجنازة رجال كبار في السن يريدون أجر الجنازة، ولا يصلون عند القبر إلا والناس قد دفنوا الميت؛ فهل يجوز ذلك العمل؟","title":"مشروعية الإسراع بالجنازة","answer":"الجواب: السنة الإسراع بالميت، هذه السنة، النبي  قال: أسرعوا بالجنازة، فإن تكن صالحة فخير تقدمونها إليه، وإن تكون سوى ذلك فشر تضعونه عن رقابكم لكن سرعة لا تؤذي الحاملين، ولا التابعين، سرعة متوسطة ليس فيها أذى لحامليها، وليس فيها أذى للمشيعين، ولو تأخر المشيع ولم يأت إلا عند الدفن أو بعد الدفن دعا له، وترحم عليه، والحمد لله، وله أجر المتابعة والحمد لله.نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/17279/مشروعية-الاسراع-بالجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78216.mp3","categories":["حمل الميت ودفنه"]},{"id":18264,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: حسين إسماعيل العيدروس من اليمن الديمقراطية -حضرموت- تاربة، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول ويقول:هل التوابيت والقبور والأضرحة للأموات حرام، وإذا كانت في مسجد، فماذا نعمل أنفصلها؟ أم نتركها ملتحمة بالمسجد؟ وجهونا جزاكم الله خيرًا.","title":"حكم التوابيت والأضرحة للموتى في المساجد","answer":"الجواب: السنة الدفن في الأرض لا في تابوت، ولا في غيره من الصناديق، ولا يجصص القبر ولا يزفلت، ولا يوضع فيه شيء آخر من الحديد أو الألواح أو غير ذلك، السنة أن يدفن الميت في الأرض كما دفن ﷺ في الأرض ودفن الصحابة في الأرض، وهكذا غيرهم، يحفر لهم في الأرض ويلحد له، ويجعل في الأرض: مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ [طه:55]، لكن إذا كانت الأرض رخوة مائية ضعيفة فلا مانع من جعله في تابوت، أو جعل ألواح تحته حتى تمسكه لا تنهار الأرض به، أو حجارة.. أو نحو ذلك لا بأس بذلك عند الحاجة، أما إن كانت الأرض قوية فلا حاجة إلى شيء من ذلك. أما الدفن في المسجد فلا يجوز، يجب أن تكون القبور خارج المسجد؛ لأن دفن القبور في المساجد وسيلة إلى عبادة الأموات من دون الله ، والنبي ﷺ قال: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم، كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، عن جندب بن عبد الله البجلي . هذا يدل على أنه لا يجوز اتخاذ القبور مساجد يصلى فيها، وإذا كان الأمر هكذا لم يجز أيضًا الدفن فيها؛ لأن الدفن فيها يجعل القبور مساجد. وإذا وجد في المسجد قبر وجب أن ينبش وتنقل رفاته إلى المقبرة، أما إن كان القبر هو القديم، وبني عليه مسجد وجب هدم المسجد، وأن لا يصلى فيه وأن لا يبقى، بل يهدم؛ لأنه بني على معصية الله، فلا يبقى بل تجب إزالته، ولا ينبغي أن يغتر بما وقع في بعض البلدان الإسلامية من البناء على القبور واتخاذ المساجد عليها فإن هذا منكر، وإن فعله كثير من الناس فهو منكر تجب إزالته على ولاة الأمور، يجب على ولاة أمر المسلمين أن يزيلوا هذا المنكر، وأن لا يبنوا على القبور وأن لا يتخذوا عليها المساجد؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، وكذلك لا تجصص، ولا يبنى عليها قبة، ولا أي بناء، لما ثبت عن رسول الله عليه الصلاة والسلام من حديث جابر أنه: «نهى عن تجصيص القبور والقعود عليها والبناء عليها»، رواه مسلم في الصحيح. فالقبر لا يبنى عليه، لا قبة ولا غيرها ولا يجصص ولا يتخذ عليه قبة ولا مسجدًا، كل هذا منكر، وإن فعله بعض الناس كما قد يوجد في مصر والشام والعراق وغير ذلك، كله غلط. نسأل الله أن يوفق ولاة الأمور في كل مكان لإزالة هذه المساجد، وإبقاء القبور على الطريقة المحمدية التي درج عليها رسول الله عليه الصلاة والسلام في مقابر مكشوفة لا يبنى عليها، لا مساجد ولا غيرها، ولا تجصص ولا تعظم بفعل بأي شيء، بل الواجب أن يدفن الموتى في الأرض كما كان الرسول يفعل عليه الصلاة والسلام في المدينة، وكما فعله المسلمون بعده، والبناء عليها واتخاذ القباب وسيلة إلى عبادتها من دون الله، وسؤالها والاستغاثة بها والنذر لها، والذبح لها، وهذا هو الشرك الأكبر، كما قد وقع، وقد يطاف بالقبور إذا وضعت في المساجد كما قد يفعل ذلك كثير من الناس في قبور معروفة. وبسبب هذا الغلو وقع الشرك في الناس لما بني على القبور وعظمت ظن العامة أنها تدعى من دون الله وأنه يستغاث بها وأنه يطاف بها ففعلوا، فوقع الشرك الأكبر، والعياذ بالله. نسأل الله للجميع العافية والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/17313/حكم-التوابيت-والاضرحة-للموتى-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_909/nour_90905.mp3","categories":["حمل الميت ودفنه","المساجد ومواضع السجود"]},{"id":18311,"question":"يقول السائل: هل يكشف عن وجه الميت في القبر عند وضعه في اللحد؟","title":"حكم كشف وجه الميت في القبر","answer":"الجواب: لا، لا يكشف، يستر جميع بدنه حتى الوجه لا المرأة ولا الرجل، المشروع: أنه يستر وجهه وغيره بالكفن ولا يكشف شيء. نعم.","link":"https://binbaz.org.sa/fatwas/17361/حكم-كشف-وجه-الميت-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91304.mp3","categories":["حمل الميت ودفنه"]},{"id":18669,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية، محافظة الأنبار، ناحية الكرمى، وباعث الرسالة أخونا حامد كاظم جاسم، أخونا له ثلاثة أسئلة، يقول في أحد أسئلته: إذا مات الشخص عندنا لا يصلون عليه صلاة الجنازة إلا في المقبرة، فهل هذا جائز؟وإذا أردنا دفنه صاح الجميع بصوت مرتفع لا إله إلا الله طوال فترة الدفن، وإذا أراد أحد أن يساعد أخاه في عملية الدفن طلب منه المجرفة بقوله: وحد الله، ثم بعد الفراغ من الدفن يقف الملقن على قبر الميت، فيقول كلامًا بليغًا يخاطب فيه الميت، قد يؤثر في السامعين لما فيه من عبارات التذكير بعذاب القبر ونعيمه، فما الحكم في كل هذا؟أفيدونا أثابكم الله، وسدد خطاكم.","title":"حكم صلاة الجنازة في المقبرة والتهليل عند الدفن","answer":"الجواب: أما الصلاة على الميت في المقبرة فلا بأس، فقد صلى النبي ﷺ على قبر بعدما دفن، لكن الأفضل أن يصلى عليه في المصلى المعد للجنازة أو المساجد حتى يصلي عليه جمع غفير من الناس، الأفضل لأهله أن يقدموه للمسلمين يصلون عليه في المساجد، أو في المصلى المعد لصلاة الجنازة إذا كان هناك مصلى معد لصلاة الجنازة، فإن لم يتيسر ذلك قد صُلي عليه في المقبرة فلا حرج. أما رفع الصوت بلا إله إلا الله عند الدفن، أو عند الحفر، أو عند السير بالجنازة هذا لا أصل له، بل المشروع أن الإنسان يفكر وينظر في عاقبة الموت، وما بعد الموت، ويحاسب نفسه، ولا يرفع صوته بذكر الله، ولا بغير ذلك مع الجنازة، ولا عند الدفن، ولا عند الحفر، أما كون الإنسان يتكلم بشيء عادي....، سيره من الجنازة بينه وبين نفسه من دعاء، أو ذكر لله، أو في المقبرة، أو غير ذلك فلا بأس. أما شيء متعمد، صوت عالي: وحدوه، أو لا إله إلا الله، صوت جماعي أو عند الدفن، فهذا شيء لا أصل له. وكان من عادة السلف -رحمة الله عليهم- غض الصوت عند الجنائز، والتفكير في أحوال الميت، وما يقال له، وما يقول، هكذا ينبغي للمؤمن أن يفكر عند اتباعه الجنازة، وعند حضوره للقبور، وعند حضوره الدفن، يفكر في هذه الأمور العظيمة، وماذا يقال للميت؟ وماذا يقول؟ وهل يجيب أو ما يجيب؟ يكون عنده في هذا تفكير طويل حتى ينتفع بذلك. ولا مانع من الدعاء والاستغفار بين العبد وبين نفسه، والذكر بين العبد وبين نفسه، لا بأس بهذا، أما تعمد رفع الصوت بذلك، أو أن يكون صوتًا جماعيًا فهذا لا أصل له، والسنة بعد الدفن أن يدعى للميت بالمغفرة والثبات. كان النبي ﷺ إذا فرغ من دفن الميت يقول: استغفروا لأخيكم، واسألوا له التثبيت، فإنه الآن يسأل فالسنة أن يوقف عليه بعد الدفن و يدعى له بالمغفرة والثبات. أما التلقين فهو بدعة هذا الصواب، أن يقال للميت بعد الدفن: يا فلان اذكر ما خرجت عليه من الدنيا، أنك تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، وأن الإسلام دينك، وأن محمدًا نبيك، وأن القرآن إمامك، إلى غير هذا من الكلمات اللي يقولون هذا لا أصل له، جاء فيه أخبار، لكنها موضوعة غير صحيحة. والصواب في هذا، والمعتمد في هذا عند أهل السنة أن التلقين لا أصل له في سنة الرسول ﷺ بل هو بدعة، وإنما يدعى للميت بالمغفرة والثبات بعد الدفن كما أمر النبي ﷺ بذلك، هذا هو المعتمد، وهذا هو المشروع، والله المستعان، نعم. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17785/حكم-صلاة-الجنازة-في-المقبرة-والتهليل-عند-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92004.mp3","categories":["الصلاة على الميت","حمل الميت ودفنه","قضايا المرأة"]},{"id":18720,"question":"يقول هذا السائل: في بعض البلاد، وعندما تشيع الجنازة؛ ينتشر عادة بين كثير من المسلمين، فعندما يرون النعش المحمول به الميت يقومون بالإشارة إليه بسبابتهم، وينطقون بالشهادة، فما رأيكم في ذلك سماحة الشيخ؟","title":"المشروع عند رؤية الجنازة","answer":"الجواب: لا أعلم له أصلًا، لكن السنة إذا رأوها أن يقوموا النبي ﷺ قال: إذا رأيتم الجنازة فقوموا؛ فإن للموت فزعًا فالأفضل أن يقوم إذا رآها حتى تخلفه حتى تتجاوز وليس بواجب؛ لأن الرسول ﷺ قام وقعد؛ دل على أنه ليس بواجب القيام، لكن سنة.  أما الإشارة بالأصبع ما أعرف له أصلًا، والشهادة ما أعرف لها أصلًا، نعم.","link":"https://binbaz.org.sa/fatwas/17841/المشروع-عند-روية-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78903.mp3","categories":["حمل الميت ودفنه"]},{"id":19152,"question":"يقول أخونا: يوجد في بلدتنا عادة وهي: أنه عندما يتوفى الإنسان يوضع في قبر لقريب له إذا مر عليه سنة أو أكثر، فهل هذا يصح؟","title":"حكم دفن اثنين في قبر واحد","answer":"الجواب: السؤال فيه إجمال: فإذا كان مراد السائل أن الميت الجديد يدفن مع الميت القديم سنة ثم ينقل هذا لا يجوز، بل يدفن في قبر مستقل، ولا يجوز أن يدفن مع الموتى السابقين إلا للضرورة، إذا كان ضرورة قصوى ما عندهم أرض، أو في خوف أو أموات كثيرين كثر عليهم الأموات فلا مانع من دفن اثنين والثلاثة جميعًا كما فعل النبي يوم أحد عليه الصلاة والسلام. وإلا فالواجب أن يكون كل واحد على حدة، يقبر على حدة، يحفر له على حدة، ويدفن على حدة، كما هو السنة المتبعة في موتى المسلمين من عهد النبي عليه الصلاة والسلام. أما إن كان قصد السائل أنه يحفر لقريب له قبر، ثم إذا مات بعض الأقرباء دفن في هذا القبر الذي ما مات قريبه بل معد لقريبه، ولكنه لم يمت القريب ودفن هذا في قبره إذا سمحوا بذلك فلا بأس به.\nإذا كان معدًا لزيد ثم مات قريبه قبل أن يموت زيد فدفن في قبر زيد المعد له بإذن أهله فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/18325/حكم-دفن-اثنين-في-قبر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93202.mp3","categories":["حمل الميت ودفنه"]},{"id":19379,"question":"رسالةٌ وصلت إلى البرنامج من المستمع (أ. ع. أ) من المنطقة الشرقية، يسأل فيها عددًا من الأسئلة، يقول في أحدها: ما هي آداب دفن الميت في الإسلام؟","title":"آداب دفن الميت","answer":"الجواب: السنة في دفن الميت أن يكون له لحدٌ، هذا الأفضل، لحدٌ في قبلي القبر بقدره، ثم يُدفن على جنبه الأيمن، ويُوجه إلى القبلة، ثم يُنصب اللبن عليه نصبًا، ويُسد الخلل بالطين، ثم يُهال عليه التراب، ويُرفع قبره عن الأرض قدر شبرٍ؛ حتى يُعلم أنه قبرٌ. هذا هو السنة في دفن أموات المسلمين: أن يُحفر ويُعمق القبر إلى السُّرة -سُرة الرجل القائم ونحو ذلك-، ويكون له لحدٌ، هذا هو الأفضل، في جهته القبلية بقدر الميت، ثم يُوضع الميت فيه على جنبه الأيمن، ويقول: بسم الله، عند وضعه: بسم الله، وعلى مِلة رسول الله ﷺ. ثم يُنصب عليه اللبن، ويُسد الخلل؛ حتى لا يدخل عليه التراب، ثم يُهال عليه التراب، ويُرفع القبر قدر شبرٍ؛ حتى يُعرف أنه قبرٌ ولا يُمتهن. هذا هو السنة، ثم يُرش بالماء، ويُوضع عليه الحصباء، وتُوضع الأنصبة على طرفي القبر: لَبِنة لَبِنة عند طرفيه؛ حتى يُعرف أنه قبرٌ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18601/اداب-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73920.mp3","categories":["حمل الميت ودفنه"]},{"id":19427,"question":"ما حكم قراءة سورة يس وسورة الملك في أثناء دفن الميت، وبصوت مرتفع؟","title":"حكم قراءة يس والملك عند دفن الميت","answer":"الجواب: لا يقرأ عند دفنه لا يس ولا الملك ولا غيرهما ليس هذا بمشروع، لا يقرأ القرآن عند دفنه ولا بعد دفنه كله غير مشروع، وإنما تقرأ يس عند المحتضر، يستحب أن تقرأ عند المحتضر الذي لم يمت ليسمعها ويستفيد. وإذا قرئ عنده غيرها أيضًا فلا بأس من القرآن أو الأحاديث كل هذا لا بأس به، ليستفيد ويكون ذلك أقرب إلى استحضاره عظمة الله وإخلاصه لله ودعائه إياه . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18654/حكم-قراءة-يس-والملك-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93704.mp3","categories":["حمل الميت ودفنه"]}]
